function ensureTableScenes(){TABLE_HOME_SCENES.forEach(seed=>{let current=S.services.find(x=>x.id===seed.id);if(!current)S.services.push({...seed,source:'iCAR 官方',mode:'提醒并执行',record:'暂无记录',tableScene:true,editable:false});else Object.assign(current,{...seed,enabled:current.enabled,source:'iCAR 官方',tableScene:true,editable:false})});if(!S.services.some(x=>x.id==='route_todo_template'))S.services.push({id:'route_todo_template',icon:'✅',name:'路途待办提醒',desc:'把你定义的时间、地点和待办变成一条主动提醒场景',source:'我的场景',mode:'仅提醒',enabled:false,requires:['map'],trigger:'工作日导航回家时',actions:['提醒取快递'],record:'场景模板',template:true});S.services.filter(x=>['rain','table_parking','table_welcome'].includes(x.id)).forEach(x=>{x.enabled=false;x.legacyHidden=true;x.tableScene=false});if(!S.sceneModelV4){S.sceneModelV4=true;localStorage.setItem('icarClawV3',JSON.stringify(S))}}
function renderHome(){ensureTableScenes();document.getElementById('topAvatar').textContent=S.loggedIn?'杨':'访';document.getElementById('greeting').textContent=S.loggedIn?'早上好，杨先生':'你好，我是 Claw';document.getElementById('homeLead').textContent=!S.loggedIn?'登录后可恢复记忆与专属场景':!S.memoryOn?'当前不使用长期记忆，基础能力仍可用':'直接说需求，Claw 能理解并完成多个任务';let official=S.services.filter(x=>x.enabled&&x.source==='iCAR 官方'&&x.tableScene&&!x.legacyHidden),custom=S.loggedIn?S.services.filter(x=>x.enabled&&x.source==='我的场景'):[];document.getElementById('officialCount').textContent=`${official.length} 个运行中`;document.getElementById('customCount').textContent=`${custom.length} 个运行中`;document.getElementById('officialHomeScenes').innerHTML=renderHomeSceneList(official,'暂无运行中的推荐场景');document.getElementById('customHomeScenes').innerHTML=renderHomeSceneList(custom,S.loggedIn?'暂无已启动的自定义场景':'登录后查看我的场景');renderSkillTabs()}
function renderHomeSceneList(list,empty){return list.map(s=>{let m=depStatus(s),custom=s.source==='我的场景';return `<div class="compactService ${custom?'customScene':''}" onclick="openScene('${s.id}')"><span class="icon">${s.icon}</span><span><b>${s.name}</b><small>${m.length?'需要开启 '+m.join('、'):s.desc}</small><span class="sceneType">${custom?'点击查看并直接语音修改':'系统预置 · 点击了解详情'}</span></span><button class="quickOff" onclick="event.stopPropagation();quickCloseScene('${s.id}')">关闭</button></div>`}).join('')||`<div class="emptyScene">${empty}</div>`}
function quickCloseScene(id){let s=S.services.find(x=>x.id===id);if(!s)return;s.enabled=false;save();toast(`${s.name}已关闭，已从首页移除`)}
