function renderSkillTabs(){document.getElementById('skillTabs').innerHTML=SKILL_TABS.map((t,i)=>`<button class="skillTab ${i===activeSkillTab?'active':''}" onclick="selectSkillTab(${i})">${t.name}</button>`).join('');let t=SKILL_TABS[activeSkillTab];document.getElementById('skillTabContent').innerHTML=`<div class="tabStage"><button class="videoPlaceholder" onclick="showCategoryDemo('${t.name}')"><div><div class="playMark">▶</div><h3>${t.icon} ${t.name} · 30 秒了解</h3><p>${t.flow}</p></div></button><div class="tabSkillCards">${t.skills.map((s,i)=>{let m=TAB_SKILL_META[s]||skillMetaForTab(t.name,i);return `<article class="tabSkillCard" style="--accent:${m[1]};--wash:${m[2]}" onclick="showTabSkill('${t.name}','${s}')"><span class="tabSkillIcon">${m[0]}</span><span class="tabSkillText"><b>${s}</b><span class="skillHint">${userSkillCopy(s)}</span></span><button class="skillQuick" onclick="event.stopPropagation();showSkillAnimation('${t.name}','${s}')">快速了解</button></article>`}).join('')}</div></div>`}
function selectSkillTab(i){activeSkillTab=i;renderSkillTabs()}
function skillMetaForTab(tab,i){const sets={车辆控制:['🎛️','#768cff','#20284f'],出行助手:['🧭','#62c5ff','#17394b'],车辆知识问答:['🔧','#ff9875','#472a26'],生活服务:['🍽️','#ffb567','#46301f'],媒资娱乐:['🎧','#b68cff','#34244d'],iCAR趣玩:['✨','#72d9be','#183b37']};let m=sets[tab];return [m[0],m[1],m[2]]}
function userSkillCopy(skill){let s=(SKILL_REALITY[skill]||['','直接说出你的需求，Claw 会帮你完成。'])[1];s=s.split('；')[0].replace(/一期|当前范围|暂不/g,'').replace(/可根据用户明确描述/g,'根据你的描述').replace(/可理解/g,'理解').replace(/可响应/g,'响应').replace(/可结合/g,'结合').replace(/可将/g,'将').replace(/可查询/g,'查询').replace(/可推荐/g,'推荐').replace(/可记住/g,'记住');return s}
function experienceTheme(skill){if(skill==='测测')return 'fun-zodiac';if(skill==='神算子')return 'fun-fortune';return ''}
function experienceGlyph(skill){if(skill==='测测')return '♐';if(skill==='神算子')return '命';return (TAB_SKILL_META[skill]||['✦'])[0]}
function featureCopy(skill,tab=''){if(skill==='测测')return [['选择主题','星座、性格与默契测试'],['轻松作答','几道小题快速完成'],['专属结果','生成你的趣味画像']];if(skill==='神算子')return [['说出星座','找到今天的出行线索'],['生成今日签','看看关键词与幸运色'],['轻松解读','娱乐互动，不作严肃预测']];let copy={车辆控制:[['说出需求','描述感受、部件或多个动作'],['理解车况',`结合当前状态规划「${skill}」`],['连续执行','逐项调用车控并反馈结果']],出行助手:[['理解目的',`识别「${skill}」中的地点与条件`],['规划行程','结合路线、时间与沿途需求'],['开始出发','完成导航并持续主动提醒']],车辆知识问答:[['读取问题','结合车辆状态理解现象'],['检索知识',`调用车书与「${skill}」能力`],['给出方案','说明风险和下一步处理']],生活服务:[['理解条件','人数、时间、位置与偏好'],['筛选结果',`通过「${skill}」找到合适选项`],['协同出行','确认后衔接服务与导航']],媒资娱乐:[['理解线索','内容、人物、情绪与当前进度'],['跨源检索',`通过「${skill}」定位结果`],['直接播放','保持上下文并支持继续追问']],iCAR趣玩:[['说出玩法','一句话选择你感兴趣的主题'],['即时生成',`用「${skill}」生成专属内容`],['车内呈现','用语音、灯光或画面给出反馈']]};return copy[tab]||[['自然表达','不用记固定口令'],['智能编排','理解条件与先后顺序'],['完成反馈','任务状态实时可见']]}
function showTabSkill(tab,skill){let m=TAB_SKILL_META[skill]||skillMetaForTab(tab,0),fs=featureCopy(skill,tab);modal(`<button class="modalClose" onclick="closeModal()">×</button><section class="skillDetailHero" style="--detailAccent:${m[1]}"><div class="eyebrow">${tab}</div><h2>${skill}</h2><p>${userSkillCopy(skill)}</p><span class="detailGlyph">${experienceGlyph(skill)}</span></section><div class="detailFeatures">${fs.map(x=>`<div class="detailFeature"><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}</div><div class="actions"><button class="ghost" onclick="showSkillAnimation('${tab}','${skill}')">▶ 快速了解</button><button class="primary" onclick="startSkillExperience('${tab}','${skill}')">🎙 语音体验</button></div>`)}
function showCategoryDemo(tab){let t=SKILL_TABS.find(x=>x.name===tab);modal(`<button class="modalClose" onclick="closeModal()">×</button><div class="eyebrow">${t.name} · 动画演示</div><h2>${t.icon} 一句话，Claw 帮你连续完成</h2><p class="sub">${t.flow}</p><div class="demoTimeline"><span class="active">说出需求</span><span>理解上下文</span><span>调用相关能力</span><span>完成并反馈</span></div><div class="actions"><button class="primary" onclick="startSkillExperience('${tab}','${t.skills[0]}')">进入体验</button></div>`)}
function showSkillAnimation(tab,skill){let steps=featureCopy(skill,tab);modal(`<button class="modalClose" onclick="closeModal()">×</button><div class="eyebrow">${tab} · 快速了解</div><h2>${experienceGlyph(skill)} ${skill}</h2><div class="skillMedia"><div class="mediaFrame"><div class="demoScene"><div class="demoGlyph">${experienceGlyph(skill)}</div><div class="demoSignal"><i></i><i></i><i></i></div><h3>演示正在播放</h3><p>${userSkillCopy(skill)}</p></div></div><div class="mediaSteps">${steps.map((x,i)=>`<div class="mediaStep"><i>${i+1}</i><span><b>${x[0]}</b><span>${x[1]}</span></span></div>`).join('')}<div class="mediaStep"><i>✓</i><span><b>完成并反馈</b><span>识别、编排和执行状态都在同一张卡片内更新</span></span></div></div></div><div class="actions"><button class="ghost" onclick="closeModal()">关闭</button><button class="primary" onclick="startSkillExperience('${tab}','${skill}')">🎙 立即语音体验</button></div>`)}
let experienceSequence=0,experienceCtx={tab:'',skill:'',transcript:'',recognition:null,timers:[],tasks:[],cancelled:true,sessionId:0};
function voiceExample(tab,skill){if(tab==='全局语音')return '导航回家，再放点轻松的歌';if(skill==='测测')return '测测我是什么类型的旅行搭子';if(skill==='神算子')return '我是天秤座，帮我看看今天的出行运';let x={车辆控制:'有点冷，空调升两度，座椅加热一档',出行助手:'导航回家，顺路找一家好停车的咖啡店',车辆知识问答:'方向盘上的这个提示灯是什么意思',生活服务:'找一家适合四个人聚餐的本帮菜并导航过去',媒资娱乐:'放点适合夜晚开车听的歌',iCAR趣玩:'给今天的旅程制造一点惊喜'};return x[tab]||skill}
function startHomeVoice(){startSkillExperience('全局语音','Claw 全能助手')}
function startSkillExperience(tab,skill){cleanupVoiceExperience();experienceCtx={tab,skill,transcript:'',recognition:null,timers:[],tasks:[],cancelled:false,sessionId:++experienceSequence};renderListeningExperience();beginVoiceCapture(experienceCtx.sessionId)}
function themedVisual(skill){if(skill==='测测')return '<div class="zodiacWheel">♐</div>';if(skill==='神算子')return '<div class="fortuneSeal">签</div>';return `<span class="bigGlyph">${experienceGlyph(skill)}</span>`}
function renderListeningExperience(){let theme=experienceTheme(experienceCtx.skill);modal(`<div class="experienceHead"><b>${experienceCtx.skill} · 车内语音体验</b><button class="experienceClose" onclick="closeModal()">×</button></div><div class="experienceBody"><p class="experiencePrompt">请直接说出完整需求</p><div class="expVisual">${themedVisual(experienceCtx.skill)}</div><div class="voiceCapture"><div class="micOrb">🎙</div><div class="voiceWave">${'<i></i>'.repeat(7)}</div><div class="liveTranscript" id="liveTranscript">正在准备麦克风…</div><div class="voiceTip">例如：“${voiceExample(experienceCtx.tab,experienceCtx.skill)}”<br>只需说一次，Claw 会自动理解并连续执行</div></div></div>`,`experienceModal ${theme}`)}
async function beginVoiceCapture(sessionId){try{if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('secure');let stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId)return;let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)throw new Error('unsupported');let r=new SR();experienceCtx.recognition=r;r.lang='zh-CN';r.continuous=false;r.interimResults=true;r.maxAlternatives=1;r.onstart=()=>{if(experienceCtx.sessionId!==sessionId)return;let e=document.getElementById('liveTranscript');if(e)e.textContent='我在听，请说…'};r.onresult=e=>{if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId)return;let text='',finalText='';for(let i=e.resultIndex;i<e.results.length;i++){text+=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=e.results[i][0].transcript}let el=document.getElementById('liveTranscript');if(el)el.textContent=text||'我在听，请说…';if(finalText)handleVoiceCommand(finalText)};r.onerror=e=>{if(e.error!=='aborted'&&experienceCtx.sessionId===sessionId)showMicError(e.error==='not-allowed'?'permission':'recognition')};r.onend=()=>{if(!experienceCtx.cancelled&&experienceCtx.sessionId===sessionId&&!experienceCtx.transcript&&document.getElementById('modalWrap').classList.contains('open')){let el=document.getElementById('liveTranscript');if(el)el.textContent='没有听清，正在重新聆听…';experienceCtx.timers.push(setTimeout(()=>{if(!experienceCtx.cancelled&&experienceCtx.sessionId===sessionId)try{r.start()}catch(e){}},900))}};r.start()}catch(e){if(experienceCtx.sessionId===sessionId&&!experienceCtx.cancelled)showMicError(e.message==='secure'?'secure':e.message==='unsupported'?'unsupported':'permission')}}
function showMicError(type){let copy=type==='secure'?'麦克风需要通过 localhost 或 HTTPS 打开本 Demo。直接双击 file:// 文件时，浏览器可能不会提供麦克风能力。':type==='unsupported'?'当前浏览器没有语音识别能力。请使用最新版 Chrome 或 Edge 打开。':'麦克风权限未开启。请在浏览器地址栏的权限设置中允许本页面使用麦克风，然后重新进入体验。';let el=document.querySelector('.voiceCapture');if(el)el.innerHTML=`<div class="permissionHelp"><b>暂时无法开始语音体验</b><br>${copy}</div>`}
function handleVoiceCommand(text){if(experienceCtx.transcript)return;experienceCtx.transcript=text.trim();try{experienceCtx.recognition&&experienceCtx.recognition.stop()}catch(e){}experienceCtx.tasks=buildAgentTasks(experienceCtx.tab,experienceCtx.skill,text);renderAgentBoard();runAgentTasks()}
function buildAgentTasks(tab,skill,text){let base=[['理解完整需求','识别意图、条件与任务关系'],['读取车内上下文','驾驶人、乘员、车辆与环境状态']],middle;if(tab==='全局语音'){middle=[];if(/导航|回家|公司|路线|目的地|停车/.test(text))middle.push(['规划出行任务','解析目的地、路线偏好与途经需求'],['调用地图技能','生成路线并准备开始导航']);if(/空调|座椅|车窗|车门|灯|加热|温度/.test(text))middle.push(['生成车控方案','核对车辆状态与安全条件'],['调用车辆控制','按顺序执行座舱与车辆设置']);if(/歌|音乐|新闻|播客|播放|电影/.test(text))middle.push(['理解内容偏好','结合行程与当前氛围筛选内容'],['调用媒体技能','找到内容并准备播放']);if(/餐厅|吃饭|咖啡|订座|机票|火车票/.test(text))middle.push(['检索生活服务','结合人数、位置、时间和偏好'],['协同服务与地图','准备结果并衔接路线']);if(!middle.length)middle=[['Master Agent 规划','拆分任务并选择最合适的能力'],['调用相关技能','按依赖关系连续执行']]}else middle={车辆控制:[['生成车控方案','拆解设备、参数与执行顺序'],['调用车辆控制','空调、座椅及相关车设']],出行助手:[['规划完整行程','目标、途经点与路线偏好'],['协同地图与服务','导航、沿途搜索与停车']],车辆知识问答:[['检索车辆知识','结合车辆状态与车书内容'],['生成处理建议','解释原因、风险与下一步']],生活服务:[['搜索合适结果','位置、人数、时间与偏好'],['协同生活服务','筛选结果并规划路线']],媒资娱乐:[['理解内容偏好','场景、情绪与历史喜好'],['调用媒体服务','检索内容并准备播放']],iCAR趣玩:[['生成趣玩内容','结合主题与角色风格'],['渲染专属体验','生成结果与车内反馈']]}[tab]||[['Master Agent 规划','拆分任务与调用顺序'],['调用相关技能','执行当前任务']];if(skill==='测测')middle=[['解析测试主题','识别旅行、性格或星座方向'],['生成专属画像','组合趣味标签与结果']];if(skill==='神算子')middle=[['解析星座与主题','提取生日、星座和出行诉求'],['生成今日签文','组合关键词、幸运色与建议']];return [...base,...middle,['完成并反馈','同步执行结果，等待继续对话']].map(x=>({name:x[0],detail:x[1],status:'pending'}))}
function renderAgentBoard(){let theme=experienceTheme(experienceCtx.skill);modal(`<div class="experienceHead"><b>${experienceCtx.skill} · Master Agent 正在执行</b><button class="experienceClose" onclick="closeModal()">×</button></div><div class="experienceBody"><div class="agentBoard"><aside class="agentSummary"><small>已识别语音</small><p>“${escapeHtml(experienceCtx.transcript)}”</p></aside><div><div class="taskFlow" id="agentTaskFlow">${experienceCtx.tasks.map((t,i)=>`<div class="agentTask" id="agentTask${i}"><span class="taskDot">${i+1}</span><span><b>${t.name}</b><span>${t.detail}</span></span><em>等待</em></div>`).join('')}</div><div id="agentFinal"></div></div></div></div>`,`experienceModal ${theme}`)}
function runAgentTasks(){let i=0;function next(){if(i>0)setTaskState(i-1,'done');if(i>=experienceCtx.tasks.length){showAgentResult();return}setTaskState(i,'running');i++;experienceCtx.timers.push(setTimeout(next,650+Math.random()*350))}next()}
function setTaskState(i,state){let el=document.getElementById('agentTask'+i);if(!el)return;el.className='agentTask '+state;el.querySelector('.taskDot').textContent=state==='done'?'✓':'↻';el.querySelector('em').textContent=state==='done'?'完成':'执行中';el.scrollIntoView({block:'nearest',behavior:'smooth'})}
function agentResult(skill){if(experienceCtx.tab==='全局语音')return '已理解你的完整需求，并按照依赖关系完成规划与执行。';if(skill==='测测')return '已生成你的「自由探索型旅行搭子」画像：好奇、松弛，幸运方向西南。';if(skill==='神算子')return '今日关键词是“从容”，幸运色为琥珀橙；提前十分钟出发，旅程会更舒展。仅供轻松娱乐。';let x={车辆控制:'车内舒适设置已按你的描述完成。',出行助手:'路线与沿途任务已规划，正在开始导航。',车辆知识问答:'已完成车辆知识检索，并给出对应处理建议。',生活服务:'已经找到符合条件的结果，并准备好前往路线。',媒资娱乐:'已找到符合当前场景的内容并开始播放。',iCAR趣玩:'专属趣玩内容已经生成。'};return x[experienceCtx.tab]||'任务已经全部完成。'}
function showAgentResult(){let text=agentResult(experienceCtx.skill),el=document.getElementById('agentFinal');if(el)el.innerHTML=`<div class="finalAnswer"><b>✓ 已全部完成</b><br>${text}<br><small>可以继续直接说，Claw 会保持当前上下文。</small></div>`;speakText(text)}
function speakText(text){try{speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=1.02;speechSynthesis.speak(u)}catch(e){}}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cleanupVoiceExperience(){experienceCtx.cancelled=true;(experienceCtx.timers||[]).forEach(clearTimeout);try{if(experienceCtx.recognition){experienceCtx.recognition.onend=null;experienceCtx.recognition.onresult=null;experienceCtx.recognition.onerror=null;experienceCtx.recognition.abort()}}catch(e){}try{speechSynthesis.cancel()}catch(e){}}
function openSkillDetail(i){let x=SKILLS[i];modal(`<button class="modalClose" onclick="closeModal()">×</button><div class="eyebrow">CLAW 场景技能</div><h2>${x.icon} ${x.name}</h2><p class="sub">${x.intro}</p><div class="statusline">${x.tags.map(t=>`<span class="badge">${t}</span>`).join('')}</div><div class="block" style="margin-top:22px"><div class="eyebrow">试试对我说</div>${x.phrases.map((p,n)=>`<div class="row"><div><h3>“${p}”</h3><p>${n===0?'直接说需求，不必记固定口令':'也可以包含条件、程度和先后顺序'}</p></div><button class="secondary small" onclick="closeModal();tryPhrase('${p}')">试着说</button></div>`).join('')}</div><p class="sub">涉及账号授权、隐私数据或高风险车辆操作时，Claw 会先说明并等待确认。</p><div class="actions"><button class="ghost" onclick="closeModal()">返回技能中心</button></div>`)}
function tryPhrase(text){startHomeVoice()}
function serviceCard(s){let m=depStatus(s),official=s.source==='iCAR 官方';return `<div class="service"><div class="cardTop"><span class="icon">${s.icon}</span><span class="badge ${m.length?'warn':s.enabled?'ok':''}">${s.template?'场景模板':m.length?'待开启':s.enabled?'已开启':'已关闭'}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="statusline"><span class="badge">${official?'🔒 系统预置':s.template?'🎙 语音创建':'🎙 我的场景'}</span>${m.length?`<span class="badge warn">开启 ${m.join('、')}</span>`:''}</div><div class="serviceFoot"><button class="link" onclick="openScene('${s.id}')">${official?'查看详情':s.template?'用语音创建':'查看并语音修改'}</button>${s.template?'':`<button class="switch ${s.enabled?'on':''}" onclick="event.stopPropagation();toggleService('${s.id}')"><i></i></button>`}</div></div>`}
function renderServices(){let visible=S.services.filter(x=>!x.legacyHidden),act=visible.filter(x=>x.enabled),rec=visible.filter(x=>!x.enabled);document.getElementById('activeServices').innerHTML=act.map(serviceCard).join('')||'<p class="sub">暂无已开启服务</p>';document.getElementById('recommendations').innerHTML=rec.map(serviceCard).join('')+`<div class="service"><div class="cardTop"><span class="icon">✨</span><span class="badge">习惯建议</span></div><h3>下班音乐习惯</h3><p>最近 5 次下班上车，你都会调至 24°C 并播放周杰伦。</p><div class="serviceFoot"><button class="link" onclick="habitFlow()">查看推荐依据</button></div></div>`;let mine=S.loggedIn?visible.filter(x=>x.source==='我的场景'&&!x.template):[];document.getElementById('myScenes').innerHTML=mine.map(serviceCard).join('');document.getElementById('myScenesBlock').classList.toggle('hidden',!S.loggedIn);let notes=[];if(!S.memoryOn)notes.push('我的记忆已关闭：个性化温度、路线与音乐推荐将降级');if(!S.cabinEnv)notes.push('座舱环境感知已关闭：空气质量守护无法判断触发条件');if(!S.outside)notes.push('车外感知已关闭：哨兵、停车和找车能力受限');document.getElementById('serviceNotice').innerHTML=notes.map(x=>`<div class="notice">${x}</div>`).join('')}
function toggleService(id){let s=S.services.find(x=>x.id===id);if(!s)return;s.enabled=!s.enabled;let miss=depStatus(s);save();toast(`${s.name}已${s.enabled?'开启':'暂停'}${s.enabled&&miss.length?'，所需权限恢复后将完整运行':''}`)}
let sceneEditSequence=0,sceneEditCtx={id:null,recognition:null,timers:[],transcript:'',cancelled:true,sessionId:0,patch:null,before:null};
function sceneVisualMarkup(s){let official=s.source==='iCAR 官方',miss=depStatus(s);return `<button class="modalClose" onclick="closeModal()">×</button><section class="sceneVisualHero" style="--sceneAccent:${s.accent||'#7488ff'}"><span class="sceneTypePill">${official?'🔒 系统预置':s.template?'🎙 我的场景模板':'🎙 我的场景'}</span><h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.desc)}</p><span class="sceneGlyph">${s.icon}</span></section>${miss.length?`<div class="notice">开启 ${miss.join('、')} 后，这个场景即可完整运行。</div>`:''}<div class="sceneInfoGrid"><div class="sceneInfo"><small>何时主动出现</small><b>${escapeHtml(s.trigger)}</b></div><div class="sceneInfo"><small>Claw 自动完成</small><b>${s.actions.map(escapeHtml).join(' → ')}</b></div><div class="sceneInfo"><small>执行与反馈</small><b>${escapeHtml(s.mode||'提醒并执行')}<br>${escapeHtml(s.record||'暂无执行记录')}</b></div></div>`}
function openScene(id){cleanupVoiceExperience();cleanupSceneVoice();let s=S.services.find(x=>x.id===id);if(!s)return;if(s.source==='我的场景'&&!S.loggedIn){pendingTask=()=>openScene(id);loginFlow('登录后即可恢复并语音修改这个场景。');return}let official=s.source==='iCAR 官方';modal(`${sceneVisualMarkup(s)}${official?`<div class="readOnlyHint"><span>🔒 触发规则和执行逻辑由 iCAR 维护，不可编辑；你可以随时关闭或重新开启。</span></div><div class="actions"><button class="ghost" onclick="closeModal()">关闭</button><button class="primary" onclick="toggleService('${s.id}');closeModal()">${s.enabled?'关闭场景':'开启场景'}</button></div>`:`<div class="sceneVoiceZone" id="sceneVoiceZone"><div class="voiceCapture"><div class="micOrb">🎙</div><div class="voiceWave">${'<i></i>'.repeat(7)}</div><div class="liveTranscript" id="sceneEditTranscript">正在准备麦克风…</div><div class="voiceTip">请直接说怎么改，例如：“改成工作日六点半触发，空调 23 度，再播放轻音乐”<br>识别后会自动检查并保存，不需要逐步点击。</div></div></div>`}`);if(!official)beginSceneEditCapture(id)}
function detail(id){openScene(id)}
function editScene(id){let s=S.services.find(x=>x.id===id);if(!s)return;if(s.source==='iCAR 官方'){openScene(id);toast('系统预置场景只支持查看和开关');return}openScene(id)}
function saveScene(id){let s=S.services.find(x=>x.id===id);if(!s||s.source==='iCAR 官方'){toast('系统预置场景不可编辑');return}openScene(id)}
function cleanupSceneVoice(){sceneEditCtx.cancelled=true;(sceneEditCtx.timers||[]).forEach(clearTimeout);try{if(sceneEditCtx.recognition){sceneEditCtx.recognition.onend=null;sceneEditCtx.recognition.onresult=null;sceneEditCtx.recognition.onerror=null;sceneEditCtx.recognition.abort()}}catch(e){}}
async function beginSceneEditCapture(id){cleanupSceneVoice();let sessionId=++sceneEditSequence;sceneEditCtx={id,recognition:null,timers:[],transcript:'',cancelled:false,sessionId,patch:null,before:null};try{if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('secure');let stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());if(sceneEditCtx.cancelled||sceneEditCtx.sessionId!==sessionId)return;let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)throw new Error('unsupported');let r=new SR();sceneEditCtx.recognition=r;r.lang='zh-CN';r.continuous=false;r.interimResults=true;r.onstart=()=>{let el=document.getElementById('sceneEditTranscript');if(el)el.textContent='我在听，请直接说要改什么…'};r.onresult=e=>{if(sceneEditCtx.cancelled||sceneEditCtx.sessionId!==sessionId)return;let text='',finalText='';for(let i=e.resultIndex;i<e.results.length;i++){text+=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=e.results[i][0].transcript}let el=document.getElementById('sceneEditTranscript');if(el)el.textContent=text||'我在听…';if(finalText)handleSceneEditVoice(finalText)};r.onerror=e=>{if(e.error!=='aborted'&&sceneEditCtx.sessionId===sessionId)showSceneMicError(e.error==='not-allowed'?'permission':'recognition')};r.onend=()=>{if(!sceneEditCtx.cancelled&&sceneEditCtx.sessionId===sessionId&&!sceneEditCtx.transcript&&document.getElementById('sceneVoiceZone')){let el=document.getElementById('sceneEditTranscript');if(el)el.textContent='没有听清，正在重新聆听…';sceneEditCtx.timers.push(setTimeout(()=>{if(!sceneEditCtx.cancelled&&sceneEditCtx.sessionId===sessionId)try{r.start()}catch(e){}},900))}};r.start()}catch(e){if(sceneEditCtx.sessionId===sessionId&&!sceneEditCtx.cancelled)showSceneMicError(e.message==='secure'?'secure':e.message==='unsupported'?'unsupported':'permission')}}
function showSceneMicError(type){let copy=type==='secure'?'请通过 HTTPS 页面打开 Demo，才能使用车内语音体验。':type==='unsupported'?'当前浏览器不支持语音识别，请使用最新版 Chrome 或 Edge。':'请在地址栏的网站权限中允许麦克风，然后重新打开场景卡片。';let el=document.getElementById('sceneVoiceZone');if(el)el.innerHTML=`<div class="permissionHelp"><b>暂时无法开始语音修改</b><br>${copy}</div>`}
function actionCategory(a){if(/空调|温度/.test(a))return'air';if(/座椅/.test(a))return'seat';if(/导航|路线/.test(a))return'nav';if(/播放|音乐|歌曲|新闻|播客|周杰伦/.test(a))return'media';if(/提醒/.test(a))return'remind';return a}
function parseScenePatch(text,s){let p={name:null,trigger:null,addActions:[],removeCategories:[],mode:null,changes:0};let name=text.match(/(?:改名为|名称改为|名字改成|叫做)\s*[“「]?([^，。,.“”」]{2,12})/);if(name){p.name=name[1].trim();p.changes++}let trigger=[];if(/工作日/.test(text))trigger.push('工作日');else if(/周末/.test(text))trigger.push('周末');else if(/每天/.test(text))trigger.push('每天');let time=text.match(/(?:早上|上午|中午|下午|晚上)?\s*(?:\d{1,2}(?::\d{2}|点(?:半|\d{1,2}分)?)|[一二三四五六七八九十两]{1,3}点半?)/);if(time)trigger.push(time[0].replace(/\s/g,''));let place=text.match(/公司附近|到公司后?|到家后?|上车后?|下车后?|锁车后?|导航(?:开始|完成)后?/);if(place)trigger.push(place[0]);if(trigger.length){p.trigger=[...new Set(trigger)].join(' · ');p.changes++}let removing=/不要|取消|去掉|删除/.test(text);let rules=[{cat:'air',re:/空调(?:调到|设为|改到|改成)?\s*(\d{2})(?:度|°C)?/,make:m=>`空调 ${m[1]}°C`},{cat:'seat',re:/座椅(?:加热|通风)(?:调到|设为)?\s*([一二三123]档)?/,make:m=>`座椅${/通风/.test(m[0])?'通风':'加热'}${m[1]||'一档'}`},{cat:'nav',re:/导航(?:到|去|回)?([^，。,.再]{1,10})/,make:m=>`导航${m[1]==='家'?'回家':'到'+m[1]}`},{cat:'media',re:/(?:播放|放|听)(?:一点|点)?([^，。,.再]{0,10}(?:音乐|歌|新闻|播客|周杰伦))/,make:m=>`播放${m[1]||'音乐'}`},{cat:'remind',re:/提醒(?:我)?([^，。,.再]{1,14})/,make:m=>`提醒${m[1]}`}];rules.forEach(r=>{let m=text.match(r.re);if(!m)return;if(removing)p.removeCategories.push(r.cat);else p.addActions.push({cat:r.cat,value:r.make(m)});p.changes++});if(/只提醒|仅提醒/.test(text)){p.mode='仅提醒';p.changes++}else if(/自动执行|直接执行|提醒并执行/.test(text)){p.mode='提醒并执行';p.changes++}return p}
function handleSceneEditVoice(text){if(sceneEditCtx.transcript)return;sceneEditCtx.transcript=text.trim();try{sceneEditCtx.recognition&&sceneEditCtx.recognition.stop()}catch(e){}let s=S.services.find(x=>x.id===sceneEditCtx.id);if(!s||s.source!=='我的场景')return;sceneEditCtx.before={name:s.name,trigger:s.trigger,actions:[...s.actions],mode:s.mode};sceneEditCtx.patch=parseScenePatch(text,s);let tasks=[['理解语音修改','识别触发条件、动作和执行方式'],['对照当前规则','仅更新你明确提到的内容'],['检查权限与冲突','安全规则始终优先'],['更新场景配置','生成新的触发与任务编排'],['保存并同步首页','绑定当前车主账号']];let el=document.getElementById('sceneVoiceZone');if(el)el.innerHTML=`<div class="agentBoard"><aside class="agentSummary"><small>已识别语音</small><p>“${escapeHtml(text)}”</p></aside><div><div class="taskFlow">${tasks.map((t,i)=>`<div class="agentTask" id="sceneTask${i}"><span class="taskDot">${i+1}</span><span><b>${t[0]}</b><span>${t[1]}</span></span><em>等待</em></div>`).join('')}</div><div id="sceneEditFinal"></div></div></div>`;runSceneEditTasks(tasks.length)}
function runSceneEditTasks(total){let i=0;function next(){if(i>0)setSceneTaskState(i-1,'done');if(i>=total){finishSceneEdit();return}setSceneTaskState(i,'running');i++;sceneEditCtx.timers.push(setTimeout(next,560))}next()}
function setSceneTaskState(i,state){let el=document.getElementById('sceneTask'+i);if(!el)return;el.className='agentTask '+state;el.querySelector('.taskDot').textContent=state==='done'?'✓':'↻';el.querySelector('em').textContent=state==='done'?'完成':'执行中'}
function applyScenePatch(s,p){if(p.name)s.name=p.name;if(p.trigger)s.trigger=p.trigger;let actions=[...s.actions];p.removeCategories.forEach(cat=>actions=actions.filter(a=>actionCategory(a)!==cat));p.addActions.forEach(x=>{actions=actions.filter(a=>actionCategory(a)!==x.cat);actions.push(x.value)});if(actions.length)s.actions=[...new Set(actions)];if(p.mode)s.mode=p.mode;if(s.template){s.template=false;s.enabled=true;s.desc='你用语音创建的路途待办场景'}s.record='刚刚 · 已通过语音修改'}
function finishSceneEdit(){let s=S.services.find(x=>x.id===sceneEditCtx.id),p=sceneEditCtx.patch,el=document.getElementById('sceneEditFinal');if(!s||!el)return;if(!p||!p.changes){el.innerHTML='<div class="permissionHelp"><b>这次没有修改</b><br>我还没听出明确的时间、动作或执行方式。可以说：“工作日六点半触发，空调 23 度，再播放轻音乐”。</div>';speakText('我还没听出明确的修改内容，请再说一次时间或要执行的动作。');return}applyScenePatch(s,p);localStorage.setItem('icarClawV3',JSON.stringify(S));renderAll();let b=sceneEditCtx.before,diffs=[];if(b.name!==s.name)diffs.push(['名称',s.name]);if(b.trigger!==s.trigger)diffs.push(['触发',s.trigger]);if(b.actions.join('|')!==s.actions.join('|'))diffs.push(['任务',s.actions.join(' → ')]);if(b.mode!==s.mode)diffs.push(['执行',s.mode]);el.innerHTML=`<div class="sceneDiff">${diffs.map(x=>`<div class="diffRow"><small>${x[0]}</small><b>${escapeHtml(x[1])}</b></div>`).join('')}</div><div class="sceneSaved"><b>✓ 已修改并保存</b><br>新的规则已同步到首页，下次命中条件时自动生效。</div>`;speakText(`${s.name}已经修改并保存，下次会按新规则执行。`);toast('场景已通过语音修改并自动保存')}
function createScene(){modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>告诉 Claw 你想要什么</h2><p class="sub">用一句话描述什么时候、想让我做什么。</p><div class="form"><textarea id="scenePrompt">以后工作日下班上车，就帮我导航回家，空调调到24度，再放点轻松的歌。</textarea></div><div class="actions"><button class="ghost" onclick="closeModal()">取消</button><button class="primary" onclick="previewScene()">让 Claw 理解</button></div>`)}
function previewScene(){modal(`<button class="modalClose" onclick="closeModal()">×</button><div class="eyebrow">Claw 已理解</div><h2>💼 下班放松</h2><div class="row"><div><h3>什么时候</h3><p>工作日 18:00 后 · 公司附近 · 本人上车</p></div></div><div class="row"><div><h3>Claw 会做</h3><p>导航回家 → 空调 24°C → 播放轻松音乐</p></div></div><div class="notice">地图已授权；媒体服务尚未授权，保存后首次执行时可继续授权。</div><div class="actions"><button class="secondary" onclick="adjustDraft()">调整一下</button><button class="primary" onclick="saveDraft()">确认创建</button></div>`)}
function adjustDraft(){modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>调整「下班放松」</h2><div class="form"><label>名称</label><input id="dName" value="下班放松"><label>触发条件</label><input id="dTrigger" value="工作日 18:00 后 · 公司附近 · 本人上车"><label>动作（每行一个）</label><textarea id="dActions">导航回家\n空调 24°C\n播放轻松音乐</textarea><label>执行方式</label><select id="dMode"><option>仅提醒</option><option selected>提醒并执行</option></select></div><div class="actions"><button class="ghost" onclick="previewScene()">返回预览</button><button class="primary" onclick="saveAdjustedDraft()">保存场景</button></div>`)}
function saveAdjustedDraft(){let d={name:document.getElementById('dName').value,trigger:document.getElementById('dTrigger').value,actions:document.getElementById('dActions').value.split('\n'),mode:document.getElementById('dMode').value};saveDraft(d)}
function saveDraft(d={name:'下班放松',trigger:'工作日 18:00 后 · 公司附近 · 本人上车',actions:['导航回家','空调 24°C','播放轻松音乐'],mode:'提醒并执行'}){if(!S.loggedIn){pendingTask=()=>saveDraft(d);loginFlow('保存场景需要登录，登录后会恢复当前草稿。');return}S.services.push({id:'custom'+Date.now(),icon:'💼',desc:'你的专属下班舒适场景',source:'我的场景',enabled:true,requires:['map','memory'],record:'暂无记录',...d});save();closeModal();toast('场景已创建，并加入“正在为你服务”')}
function habitFlow(){modal(`<button class="modalClose" onclick="closeModal()">×</button><div class="eyebrow">Claw 发现了你的习惯 ✨</div><h2>下班时的舒适与音乐</h2><p class="sub">最近 5 个工作日，18:05–18:35 在公司附近上车后，你都将空调设为 24°C，并在 3 分钟内播放周杰伦。规律置信度 92%。</p><div class="steps"><i class="done"></i><i></i><i></i></div><div class="actions"><button class="ghost" onclick="closeModal();toast('已暂时忽略这条建议')">暂时不用</button><button class="primary" onclick="habitPreview()">查看场景预览</button></div>`)}
function habitPreview(){modal(`<button class="modalClose" onclick="closeModal()">×</button><div class="eyebrow">场景预览</div><h2>✨ 下班音乐习惯</h2><p class="sub">工作日下班上车后，将空调设为 24°C，并播放周杰伦。检测到与「回家模式」触发条件相似。</p><div class="steps"><i class="done"></i><i class="done"></i><i></i></div><div class="actions"><button class="secondary" onclick="acceptHabit('merge')">合并到“回家模式”</button><button class="primary" onclick="acceptHabit('new')">新建场景</button></div>`)}
function acceptHabit(type){if(!S.loggedIn){pendingTask=()=>acceptHabit(type);loginFlow('保存习惯场景需要登录。');return}if(type==='merge'){let h=S.services.find(x=>x.id==='home');h.actions.push('空调 24°C','播放周杰伦');toast('已合并到“回家模式”')}else S.services.push({id:'habit'+Date.now(),icon:'🎵',name:'下班音乐',desc:'下班上车后准备舒适环境与音乐',source:'我的场景',mode:'提醒并执行',enabled:true,requires:['memory','media'],trigger:'工作日下班上车',actions:['空调 24°C','播放周杰伦'],record:'暂无记录'});save();closeModal();if(type==='new')toast('新场景已创建')}
function renderMemory(){let gate=document.getElementById('memoryGate'),content=document.getElementById('memoryContent');if(!S.loggedIn){gate.innerHTML='<div class="notice">我的记忆与车主账号绑定。登录后将自动加载原账号数据。 <button class="link" onclick="loginFlow()">立即登录</button></div>';content.classList.add('hidden');return}if(!S.memoryOn){gate.innerHTML='<div class="notice">我的记忆已关闭。数据仍安全保留，但 Claw 不会读取，相关页面内容已隐藏。 <button class="link" onclick="setPermission(\'memoryOn\',true)">重新开启</button></div>';content.classList.add('hidden');return}gate.innerHTML='';content.classList.remove('hidden');document.getElementById('memoryTabs').innerHTML=cats.map(c=>`<button class="${filter===c?'active':''}" onclick="filterMemory('${c}')">${c}</button>`).join('');let list=S.memories.filter(m=>filter==='全部'||m[1]===filter);document.getElementById('recentMemory').innerHTML=S.memories.slice(0,3).map(m=>`<div class="card"><span class="badge">${m[1]}</span><h3>${m[2]}</h3><p>更新于 ${m[4]}</p></div>`).join('');document.getElementById('memoryList').innerHTML=list.map(m=>`<div class="row"><div class="rowMain">${batch?`<input class="check" type="checkbox" ${selected.has(m[0])?'checked':''} onchange="selectMemory('${m[0]}',this.checked)">`:''}<div><h3>${m[2]}</h3><p>${m[1]} · 来源：${m[3]} · 更新：${m[4]}</p></div></div><div>${!batch?`<button class="ghost small" onclick="editMemory('${m[0]}')">编辑</button> <button class="danger small" onclick="deleteMemory('${m[0]}')">删除</button>`:''}</div></div>`).join('');document.getElementById('batchActions').classList.toggle('hidden',!batch);document.getElementById('batchBtn').textContent=batch?'退出批量':'批量管理'}
function filterMemory(c){filter=c;renderMemory()}function toggleBatch(){batch=!batch;selected.clear();renderMemory()}function selectMemory(id,on){on?selected.add(id):selected.delete(id)}function selectVisible(){S.memories.filter(m=>filter==='全部'||m[1]===filter).forEach(m=>selected.add(m[0]));renderMemory()}function deleteSelected(){S.memories=S.memories.filter(m=>!selected.has(m[0]));batch=false;selected.clear();save();toast('已删除所选记忆')}
function editMemory(id){let m=S.memories.find(x=>x[0]===id);modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>编辑记忆</h2><div class="form"><label>内容</label><input id="memText" value="${m[2]}"><label>分类</label><select id="memCat">${cats.slice(1).map(c=>`<option ${c===m[1]?'selected':''}>${c}</option>`)}</select></div><p class="sub">来源：${m[3]} · 最近更新：${m[4]}<br>使用场景：个性化推荐、主动服务判断</p><div class="actions"><button class="ghost" onclick="closeModal()">取消</button><button class="primary" onclick="saveMemory('${id}')">保存</button></div>`)}function saveMemory(id){let m=S.memories.find(x=>x[0]===id);m[2]=document.getElementById('memText').value;m[1]=document.getElementById('memCat').value;m[4]='刚刚';save();closeModal();toast('记忆已更新')}function deleteMemory(id){confirmBox('删除这条记忆？','删除后无法用于个性化服务。',()=>{S.memories=S.memories.filter(m=>m[0]!==id);save();toast('记忆已删除')})}function clearAllMemory(){if(!S.loggedIn||!S.memoryOn)return;confirmBox('清空全部记忆？','这会删除六类全部数据，且不同于关闭 Memory。此操作不可撤销。',()=>{S.memories=[];save();toast('全部记忆已清空')})}
function renderVoice(){let rows=[['智能唤醒总开关','允许通过唤醒词唤醒 Claw','wake',false],['唤醒词 · 你好 Claw','点击可更换唤醒词','word',true],['主驾全时免唤醒','主驾无需唤醒词即可说出指令','fullWake',true],['智能免唤醒','根据对话上下文判断是否在和 Claw 说话','smartWake',true]];document.getElementById('voiceRows').innerHTML=rows.map(r=>`<div class="row ${r[3]&&!S.wake?'disabled':''}"><div><h3>${r[0]}</h3><p>${r[1]}</p></div>${r[2]==='word'?'<button class="secondary small">更换</button>':`<button class="switch ${S[r[2]]?'on':''}" ${r[3]&&!S.wake?'disabled':''} onclick="setVoice('${r[2]}')"><i></i></button>`}</div>`).join('')}
function setVoice(k){S[k]=!S[k];if(k==='wake'&&!S.wake){S.fullWake=false;S.smartWake=false}save();toast(S.wake?'智能唤醒设置已更新':'智能唤醒已关闭，屏幕与物理入口仍可使用')}function toggleSimple(el){el.classList.toggle('on')}
function renderPrivacy(){document.getElementById('accountBlock').innerHTML=S.loggedIn?`<div class="block"><h2>车主账号</h2><div class="row"><div class="rowMain"><span class="avatar">杨</span><div><h3>杨先生</h3><p>138****2026 · 数据已同步</p></div></div><button class="danger" onclick="logoutFlow()">退出登录</button></div></div>`:`<div class="block"><h2>尚未登录</h2><div class="row"><div><h3>登录以恢复你的专属 Claw</h3><p>Memory、我的场景、身份绑定和角色引擎配置均会恢复</p></div><button class="primary" onclick="loginFlow()">登录车主账号</button></div></div>`;document.getElementById('memoryPermission').innerHTML=permRow('允许 Claw 使用我的记忆','关闭仅停止读取并隐藏内容，已有数据仍会保留','memoryOn');document.getElementById('identityRows').innerHTML=['face','voiceprint'].map(k=>{let n=k==='face'?'Face ID':'声纹识别',d=k==='face'?'上车识别车主并加载专属配置':'识别说话人并提供个性回应';return `<div class="row"><div><h3>${n}</h3><p>${d} · ${S.loggedIn&&S[k]?'已绑定当前账号':'未绑定'}</p></div><button class="switch ${S.loggedIn&&S[k]?'on':''}" role="switch" aria-label="${escapeHtml(n)}" aria-checked="${!!(S.loggedIn&&S[k])}" onclick="identityFlow('${k}')"><i></i></button></div>`}).join('');document.getElementById('cabinRows').innerHTML=permRow('乘员与座位识别','识别座位与乘员，为个性服务提供判断','cabinPeople')+permRow('座舱环境感知','使用温度、空气质量、PM2.5 等信息','cabinEnv');document.getElementById('outsideRows').innerHTML=permRow('车外环境感知','用于停车记录、找车与车外主动守护','outside');document.getElementById('thirdRows').innerHTML=Object.entries({map:'地图服务',media:'媒体服务',life:'生活服务',charge:'补能服务',service:'售后维保'}).map(([k,n])=>`<div class="row"><div><h3>${n}</h3><p>${S.third[k]?'已授权，可用于相关任务':'未授权，需要时将发起授权'}</p></div><button class="${S.third[k]?'danger':'secondary'} small" onclick="thirdAuth('${k}','${n}')">${S.third[k]?'撤销授权':'授权'}</button></div>`).join('')}
function permRow(n,d,k){return `<div class="row"><div><h3>${n}</h3><p>${d}</p></div><button class="switch ${S[k]?'on':''}" role="switch" aria-label="${escapeHtml(n)}" aria-checked="${!!S[k]}" onclick="setPermission('${k}',${!S[k]})"><i></i></button></div>`}
function setPermission(k,val){if(!val){let impacts={memoryOn:'关闭后记忆内容将隐藏；个性化推荐和依赖记忆的场景会降级。数据不会删除。',cabinEnv:'依赖座舱环境判断的服务将进入能力受限状态。',cabinPeople:'指定乘员和座位相关服务会受限。',outside:'停车记录、找车和车外安全服务会受限。'};confirmBox('确认关闭？',impacts[k],()=>{S[k]=false;save();toast('权限已关闭，相关页面已同步降级')});return}if(k==='memoryOn'&&!S.loggedIn){pendingTask=()=>setPermission(k,true);loginFlow('开启我的记忆需要登录车主账号。');return}S[k]=true;save();toast('权限已开启，相关能力已恢复')}
function identityFlow(k){let n=k==='face'?'Face ID':'声纹';if(S[k]){confirmBox(`关闭${n}？`,`将解除当前车辆上的${n}识别，但账号与其他数据保留。`,()=>{S[k]=false;save();toast(`${n}已关闭`) });return}if(!S.loggedIn){pendingTask=()=>identityFlow(k);loginFlow(`录入${n}前需要登录车主账号。`);return}modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>录入${n}</h2><p class="sub">${k==='face'?'请正视前方摄像头，缓慢转动头部。':'请清晰读出：“你好 Claw，今天也一起出发吧。”'}</p><div class="steps"><i class="done"></i><i class="done"></i><i></i></div><div class="orbCard" style="min-height:180px"><div style="font-size:70px">${k==='face'?'🙂':'🎙️'}</div></div><div class="actions"><button class="ghost" onclick="closeModal()">取消</button><button class="primary" onclick="finishIdentity('${k}')">完成录入</button></div>`)}function finishIdentity(k){S[k]=true;save();closeModal();toast(`${k==='face'?'Face ID':'声纹'}已绑定杨先生账号`)}
function thirdAuth(k,n){if(S.third[k]){confirmBox(`撤销${n}授权？`,'相关任务将进入能力受限；再次授权后可恢复。',()=>{S.third[k]=false;save();toast(`${n}授权已撤销`) });return}modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>授权${n}</h2><p class="sub">Claw 仅在完成相关任务时使用该服务。授权完成后会自动返回并继续原任务。</p><div class="steps"><i class="done"></i><i></i><i></i></div><div class="actions"><button class="ghost" onclick="closeModal()">暂不授权</button><button class="primary" onclick="finishThird('${k}','${n}')">同意并授权</button></div>`)}function finishThird(k,n){S.third[k]=true;save();closeModal();toast(`${n}授权成功${pendingTask?'，正在继续原任务':''}`);if(pendingTask){let t=pendingTask;pendingTask=null;setTimeout(t,350)}}
function runAsk(){startHomeVoice()}
function logoutFlow(){confirmBox('退出车主账号？','Memory、我的场景、身份状态和角色引擎配置将隐藏，但数据不会删除。重新登录原账号会全部恢复。',()=>{S.loggedIn=false;save();goHome();toast('已退出，基础 Claw 仍可使用')})}function loginFlow(msg='登录后将恢复原账号的数据与配置。'){modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>登录车主账号</h2><p class="sub">${msg}</p><div class="form"><label>手机号</label><input value="138 **** 2026"><label>验证码</label><input value="2026"></div><div class="actions"><button class="ghost" onclick="closeModal()">取消</button><button class="primary" onclick="finishLogin()">登录</button></div>`)}function finishLogin(){S.loggedIn=true;save();closeModal();toast('欢迎回来，账号资产已恢复');if(pendingTask){let t=pendingTask;pendingTask=null;setTimeout(t,300)}}
const ROLE_OPTIONS={
 音色:[['星野','温润可靠，适合日常陪伴'],['清岚','清晰沉稳，信息表达更利落'],['小满','轻快亲切，更有活力']],
 性格:[['温暖陪伴','会关注感受，表达更有温度'],['冷静专业','先给结论，判断清楚可靠'],['活泼有趣','更轻松，会适当加入幽默']],
 表达方式:[['简洁直接','尽量一句话说清重点'],['自然适中','重点明确，也会补充必要原因'],['解释充分','重要判断会说明依据与影响']],
 主动程度:[['重要时提醒','只在安全或重要事项时主动'],['适度主动','在合适的时候给出有价值建议'],['多给建议','更积极发现需求并询问你']],
 称呼:[['杨先生','正式、自然'],['你','更轻松亲近'],['队长','更有伙伴感']]
};
function ensureRoleConfig(){S.personal=S.personal||{};let defaults={音色:'星野',性格:'温暖陪伴',表达方式:'自然适中',主动程度:'适度主动',称呼:'杨先生'};Object.keys(defaults).forEach(k=>{if(!ROLE_OPTIONS[k].some(x=>x[0]===S.personal[k]))S.personal[k]=defaults[k]})}
function renderPersonal(){ensureRoleConfig();let icons={音色:'🎙️',性格:'💫',表达方式:'💬',主动程度:'✨',称呼:'👋'};let tips={音色:'选择你愿意长期听到的声音',性格:'决定 Claw 如何理解和回应你的情绪',表达方式:'决定回答是更简洁还是更有解释',主动程度:'决定 Claw 什么时候主动开口',称呼:'Claw 日常怎么称呼你'};document.getElementById('personalOptions').innerHTML=Object.entries(ROLE_OPTIONS).map(([g,ops])=>`<section class="roleSection"><div class="roleSectionHead"><span class="icon">${icons[g]}</span><div><h2>${g}</h2><p>${tips[g]}</p></div></div><div class="roleChoices">${ops.map(o=>`<button class="roleChoice ${S.personal[g]===o[0]?'active':''}" onclick="pickPersonal('${g}','${o[0]}')"><b>${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div></section>`).join('');document.getElementById('previewName').textContent=`${S.personal.性格} · ${S.personal.音色}`;document.getElementById('previewCall').textContent=`${S.personal.称呼} · ${S.personal.主动程度}`;let lines={温暖陪伴:'前方开始拥堵，要不要换一条更轻松的路线？',冷静专业:'前方拥堵约增加 18 分钟，建议切换备选路线。',活泼有趣:'前面有点堵，要不要跟我换条更顺的路？'};let line=lines[S.personal.性格];if(S.personal.表达方式==='简洁直接')line=S.personal.性格==='活泼有趣'?'前面堵了，换条路吗？':'前方拥堵，建议换路线。';if(S.personal.表达方式==='解释充分')line+=' 备选路线预计节省 12 分钟，且当前路况更稳定。';document.getElementById('previewLine').textContent='“'+line+'”'}
function pickPersonal(g,o){ensureRoleConfig();S.personal[g]=o;renderPersonal()}function previewRoleVoice(){ensureRoleConfig();toast(`正在试听${S.personal.音色}：${document.getElementById('previewLine').textContent}`)}function savePersonal(){ensureRoleConfig();if(!S.loggedIn){pendingTask=savePersonal;loginFlow('保存角色并跨次同步需要登录。当前选择会保留。');return}S.savedPersonal={...S.personal};save();toast('角色引擎配置已保存到车主账号')}
function openSettings(p){document.getElementById('home').style.display='none';document.getElementById('bottomNav').style.display='none';document.getElementById('settings').classList.add('open');showPage(p)}function goHome(){document.getElementById('home').style.display='';document.getElementById('bottomNav').style.display='flex';document.getElementById('settings').classList.remove('open');renderAll()}function showPage(p){document.querySelectorAll('.page,.side .item').forEach(x=>x.classList.remove('active'));document.getElementById('page-'+p).classList.add('active');document.querySelector(`[data-page="${p}"]`).classList.add('active');if(p==='memory')renderMemory()}
function modal(html,cls=''){let m=document.getElementById('modal');m.className='modal'+(cls?' '+cls:'');m.innerHTML=html;document.getElementById('modalWrap').classList.add('open')}function closeModal(){cleanupVoiceExperience();cleanupSceneVoice();let wrap=document.getElementById('modalWrap');wrap.classList.remove('open');document.getElementById('modal').innerHTML=''}function confirmBox(title,desc,fn){window._confirm=fn;modal(`<button class="modalClose" onclick="closeModal()">×</button><h2>${title}</h2><p class="sub">${desc}</p><div class="actions"><button class="ghost" onclick="closeModal()">取消</button><button class="danger" onclick="window._confirm();closeModal()">确认</button></div>`)}function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(window._tt);window._tt=setTimeout(()=>el.classList.remove('show'),2600)}
