function uiIcon(name,cls=''){return `<svg class="uiIcon ${cls}" aria-hidden="true" focusable="false"><use href="#ic-${name}"></use></svg>`}
function modalCloseButton(){return `<button class="modalClose" onclick="closeModal()" aria-label="关闭">${uiIcon('close')}</button>`}
const CATEGORY_STYLE={车辆控制:['car','#718bff'],出行助手:['route','#55c8e8'],车辆知识问答:['book','#ff9878'],生活服务:['service','#f0b65e'],媒资娱乐:['media','#a989ff'],iCAR趣玩:['sparkles','#e47fd3'],'全局语音':['sparkles','#718bff']};
function categoryStyle(tab){return CATEGORY_STYLE[tab]||['sparkles','#718bff']}
function skillIconKey(tab,skill){if(skill==='测测')return'zodiac';if(skill==='神算子')return'fortune';if(/氛围/.test(skill))return'celebration';if(/停车/.test(skill))return'parking';if(/故障|诊断|车况/.test(skill))return'diagnostic';if(/搜索|查询|问答|知识/.test(skill))return'search';if(/票/.test(skill))return'ticket';if(/餐|商品|订座/.test(skill))return'service';if(/音乐|播放|媒资|影视|新闻|哼唱/.test(skill))return'media';if(/舒适|环境|车控/.test(skill))return'sliders';return categoryStyle(tab)[0]}
function sceneIconKey(s){let id=s.id||'',n=s.name||'';if(/visibility|视野|雨|雪地|天气/.test(id+n))return'wind';if(/identity|迎宾|儿童|驾驶员/.test(id+n))return'user';if(/nav|景点|停车位置|找车|路线|沿途/.test(id+n))return'route';if(/parking|停车推荐/.test(id+n))return'parking';if(/alert|异常|事故/.test(id+n))return'warning';if(/air|空气/.test(id+n))return'leaf';if(/sentinel|守护|离车/.test(id+n))return'shield';if(/media|内容/.test(id+n))return'media';if(/memory|记忆/.test(id+n))return'memory';if(s.source==='我的场景')return'sparkles';return'car'}
function renderHomeSceneListV4(list,empty){return list.map(s=>{let m=depStatus(s),custom=s.source==='我的场景';return `<div class="compactService ${custom?'customScene':''}" onclick="openScene('${s.id}')"><span class="icon">${uiIcon(sceneIconKey(s))}</span><span><b>${escapeHtml(s.name)}</b><small>${m.length?'需要开启 '+m.join('、'):escapeHtml(s.desc)}</small><span class="sceneType">${custom?'语音调整':'系统预置 · 查看详情'}</span></span><button class="quickOff" onclick="event.stopPropagation();quickCloseScene('${s.id}')" aria-label="关闭${escapeHtml(s.name)}">${uiIcon('close')}</button></div>`}).join('')||`<div class="emptyScene">${empty}</div>`}
function renderSkillTabsV4(){let tabs=document.getElementById('skillTabs'),content=document.getElementById('skillTabContent');tabs.innerHTML=SKILL_TABS.map((t,i)=>{let st=categoryStyle(t.name);return `<button class="skillTab ${i===activeSkillTab?'active':''}" onclick="selectSkillTab(${i})">${uiIcon(st[0])}<span>${t.name}</span></button>`}).join('');let t=SKILL_TABS[activeSkillTab],st=categoryStyle(t.name);content.innerHTML=`<div class="tabStage"><div class="skillUnifiedGrid">${t.skills.map(s=>{let icon=skillIconKey(t.name,s);return `<article class="unifiedSkillCard" style="--accent:${st[1]}"><button class="skillCardOpen" onclick="showSkillDemo('${t.name}','${s}')"><span class="skillCardHead"><span class="skillVisualIcon">${uiIcon(icon)}</span><span class="skillStatus">可体验</span></span><b>${escapeHtml(s)}</b><p>${escapeHtml(userSkillCopy(s))}</p></button><div class="skillCardActions"><button class="cardAction" onclick="showSkillDemo('${t.name}','${s}')">${uiIcon('play')}<span>观看演示</span></button><button class="cardAction quick" onclick="startSkillExperience('${t.name}','${s}')">${uiIcon('mic')}<span>语音体验</span></button></div></article>`}).join('')}</div></div>`}
function sceneArtMarkup(s){let key=sceneIconKey(s);return `<div class="sceneArt"><svg class="sceneArtSvg" viewBox="0 0 340 150" role="img" aria-label="${escapeHtml(s.name)}场景插画"><path class="artRoad" d="M8 123c54-31 95-35 148-11s102 22 176-14"/><path class="artCar" d="M52 93h91l18 18v18H38v-18l14-18Zm17 0 10-19h48l16 19M58 129v8m84-8v8"/><circle class="artSignal" cx="248" cy="61" r="48"/><circle class="artSignal" cx="248" cy="61" r="37"/><use href="#ic-${key}" x="224" y="37" width="48" height="48"/><path class="artSignal" d="M173 103c20-22 35-31 55-35"/></svg></div>`}
function sceneVisualMarkupV4(s){let official=s.source==='iCAR 官方',miss=depStatus(s);return `${modalCloseButton()}<section class="sceneVisualHero v4" style="--sceneAccent:${s.accent||'#718bff'}"><div><span class="sceneTypePill">${uiIcon(official?'lock':'mic','sm')}${official?'系统预置':s.template?'我的场景模板':'我的场景'}</span><h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.desc)}</p></div>${sceneArtMarkup(s)}</section>${miss.length?`<div class="notice">开启 ${miss.join('、')} 后，这个场景即可完整运行。</div>`:''}<div class="sceneInfoGrid"><div class="sceneInfo">${uiIcon('route')}<small>何时主动出现</small><b>${escapeHtml(s.trigger)}</b></div><div class="sceneInfo">${uiIcon('sparkles')}<small>Claw 自动完成</small><b>${s.actions.map(escapeHtml).join(' → ')}</b></div><div class="sceneInfo">${uiIcon('shield')}<small>执行与反馈</small><b>${escapeHtml(s.mode||'提醒并执行')}<br>${escapeHtml(s.record||'暂无执行记录')}</b></div></div>`}
function serviceCardV4(s){let m=depStatus(s),official=s.source==='iCAR 官方';return `<div class="service"><div class="cardTop"><span class="icon">${uiIcon(sceneIconKey(s))}</span><span class="badge ${m.length?'warn':s.enabled?'ok':''}">${s.template?'场景模板':m.length?'待开启':s.enabled?'已开启':'已关闭'}</span></div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.desc)}</p><div class="statusline"><span class="badge">${uiIcon(official?'lock':'mic','sm')}${official?'系统预置':s.template?'语音创建':'我的场景'}</span>${m.length?`<span class="badge warn">开启 ${m.join('、')}</span>`:''}</div><div class="serviceFoot"><button class="link" onclick="openScene('${s.id}')">${official?'查看详情':s.template?'用语音创建':'语音调整'}</button>${s.template?'':`<button class="switch ${s.enabled?'on':''}" onclick="event.stopPropagation();toggleService('${s.id}')"><i></i></button>`}</div></div>`}
function renderServicesV4(){let visible=S.services.filter(x=>!x.legacyHidden),act=visible.filter(x=>x.enabled),rec=visible.filter(x=>!x.enabled);document.getElementById('activeServices').innerHTML=act.map(serviceCardV4).join('')||'<p class="sub">暂无已开启服务</p>';document.getElementById('recommendations').innerHTML=rec.map(serviceCardV4).join('')+`<div class="service"><div class="cardTop"><span class="icon">${uiIcon('sparkles')}</span><span class="badge">习惯建议</span></div><h3>下班音乐习惯</h3><p>最近 5 次下班上车，你都会调至 24°C 并播放周杰伦。</p><div class="serviceFoot"><button class="link" onclick="habitFlow()">查看推荐依据</button></div></div>`;let mine=S.loggedIn?visible.filter(x=>x.source==='我的场景'&&!x.template):[];document.getElementById('myScenes').innerHTML=mine.map(serviceCardV4).join('');document.getElementById('myScenesBlock').classList.toggle('hidden',!S.loggedIn);let notes=[];if(!S.memoryOn)notes.push('我的记忆已关闭：个性化温度、路线与音乐推荐将降级');if(!S.cabinEnv)notes.push('座舱环境感知已关闭：空气质量守护无法判断触发条件');if(!S.outside)notes.push('车外感知已关闭：哨兵、停车和找车能力受限');document.getElementById('serviceNotice').innerHTML=notes.map(x=>`<div class="notice">${x}</div>`).join('')}
function renderPersonalV4(){ensureRoleConfig();let icons={音色:'mic',性格:'sparkles',表达方式:'book',主动程度:'shield',称呼:'user'},tips={音色:'选择你愿意长期听到的声音',性格:'决定 Claw 如何理解和回应你的情绪',表达方式:'决定回答是更简洁还是更有解释',主动程度:'决定 Claw 什么时候主动开口',称呼:'Claw 日常怎么称呼你'};document.getElementById('personalOptions').innerHTML=Object.entries(ROLE_OPTIONS).map(([g,ops])=>`<section class="roleSection"><div class="roleSectionHead"><span class="icon">${uiIcon(icons[g])}</span><div><h2>${g}</h2><p>${tips[g]}</p></div></div><div class="roleChoices">${ops.map(o=>`<button class="roleChoice ${S.personal[g]===o[0]?'active':''}" onclick="pickPersonal('${g}','${o[0]}')"><b>${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div></section>`).join('');document.getElementById('previewName').textContent=`${S.personal.性格} · ${S.personal.音色}`;document.getElementById('previewCall').textContent=`${S.personal.称呼} · ${S.personal.主动程度}`;let lines={温暖陪伴:'前方开始拥堵，要不要换一条更轻松的路线？',冷静专业:'前方拥堵约增加 18 分钟，建议切换备选路线。',活泼有趣:'前面有点堵，要不要跟我换条更顺的路？'},line=lines[S.personal.性格];if(S.personal.表达方式==='简洁直接')line=S.personal.性格==='活泼有趣'?'前面堵了，换条路吗？':'前方拥堵，建议换路线。';if(S.personal.表达方式==='解释充分')line+=' 备选路线预计节省 12 分钟，且当前路况更稳定。';document.getElementById('previewLine').textContent='“'+line+'”'}
let demoPlayerCtx={timer:null,frames:[],index:0,elapsed:0,running:false,tab:'',skill:'',accent:'#718bff'};
function demoFrames(tab,skill){let fs=featureCopy(skill,tab);return [{title:'说出自然需求',detail:`“${voiceExample(tab,skill)}”`,icon:'mic'},...fs.map((x,i)=>({title:x[0],detail:x[1],icon:i===0?'sparkles':i===1?skillIconKey(tab,skill):'check'})),{title:'完成并反馈',detail:'每个任务的状态都在同一张卡片中自动向下更新。',icon:'check'}]}
function stopDemoTimer(){if(demoPlayerCtx.timer){clearInterval(demoPlayerCtx.timer);demoPlayerCtx.timer=null}demoPlayerCtx.running=false}
function cleanupDemoPlayer(){stopDemoTimer();demoPlayerCtx={timer:null,frames:[],index:0,elapsed:0,running:false,tab:'',skill:'',accent:'#718bff'}}
function renderDemoFrame(index){let f=demoPlayerCtx.frames[index],stage=document.getElementById('demoStageInner');if(!f||!stage)return;stage.classList.add('changing');setTimeout(()=>{if(!document.getElementById('demoStageInner'))return;stage.innerHTML=`<div class="demoStageIcon">${uiIcon(f.icon)}</div><small>步骤 ${index+1}</small><h3>${escapeHtml(f.title)}</h3><p>${escapeHtml(f.detail)}</p>`;stage.classList.remove('changing')},150);let counter=document.getElementById('demoCounter');if(counter)counter.textContent=`${index+1} / ${demoPlayerCtx.frames.length}`}
function syncDemoPlaybackUIV11(state=null,sessionId=demoPlayerCtx.sessionId){
  if(!demoPlayerCtx||demoPlayerCtx.sessionId!==sessionId)return;
  if(state)demoPlayerCtx.playbackState=state;
  let current=demoPlayerCtx.playbackState||'ready',labels={ready:'准备播放',playing:'演示播放中',paused:'已暂停',ended:'演示结束 · 可重新播放'},actions={ready:'播放演示',playing:'暂停演示',paused:'继续播放演示',ended:'重新播放演示'},button=document.getElementById('demoPlayBtn'),counter=document.getElementById('demoCounter');
  if(button){button.innerHTML=uiIcon(current==='playing'?'pause':'play');button.setAttribute('aria-label',actions[current]);button.setAttribute('title',actions[current])}
  if(counter){counter.textContent=labels[current];counter.setAttribute('role','status');counter.setAttribute('aria-live','polite')}
}
function startDemoPlayback(){
  let context=demoPlayerCtx;if(context.running||!context.frames.length)return;
  let sessionId=context.sessionId,total=context.frames.length*2.8;
  if(context.elapsed>=total){(context.timeouts||[]).forEach(clearTimeout);context.timeouts=[];context.elapsed=0;context.index=0;renderDemoFrame(0,sessionId);let bar=document.getElementById('demoProgressBar'),time=document.getElementById('demoTime');if(bar)bar.style.width='0%';if(time)time.textContent='00:00'}
  context.running=true;syncDemoPlaybackUIV11('playing',sessionId);
  context.timer=setInterval(()=>{
    if(demoPlayerCtx!==context||demoPlayerCtx.sessionId!==sessionId||!context.running)return;
    context.elapsed=Math.min(total,context.elapsed+.12);let index=Math.min(context.frames.length-1,Math.floor(context.elapsed/2.8));
    if(index!==context.index){context.index=index;renderDemoFrame(index,sessionId)}
    let bar=document.getElementById('demoProgressBar');if(bar)bar.style.width=`${Math.min(100,context.elapsed/total*100)}%`;
    let time=document.getElementById('demoTime');if(time)time.textContent=`00:${String(Math.floor(context.elapsed)).padStart(2,'0')}`;
    if(context.elapsed>=total){stopDemoTimer();syncDemoPlaybackUIV11('ended',sessionId)}
  },120)
}
function toggleDemoPlayback(){if(demoPlayerCtx.running){stopDemoTimer();syncDemoPlaybackUIV11('paused');return}startDemoPlayback()}
