function startSkillExperienceV4(tab,skill){cleanupDemoPlayer();cleanupVoiceExperience();cleanupSceneVoice();experienceCtx={tab,skill,transcript:'',recognition:null,timers:[],tasks:[],cancelled:false,sessionId:++experienceSequence,phase:'listening',awaitingConfirm:false,committed:false,recognitionActive:false};renderListeningExperienceV4();beginVoiceCaptureV4(experienceCtx.sessionId)}
async function beginVoiceCaptureV4(sessionId){let ctx=experienceCtx;if(ctx.cancelled||ctx.sessionId!==sessionId||ctx.phase!=='listening')return;try{if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('secure');let stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId||experienceCtx.phase!=='listening')return;let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)throw new Error('unsupported');let r=new SR(),finalized=false;experienceCtx.recognition=r;r.lang='zh-CN';r.continuous=false;r.interimResults=true;r.maxAlternatives=1;r.onstart=()=>{if(experienceCtx.sessionId!==sessionId||experienceCtx.cancelled)return;experienceCtx.recognitionActive=true;let e=document.getElementById('liveTranscript');if(e)e.textContent='我在听，请完整说出需求…'};r.onresult=e=>{if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId||experienceCtx.phase!=='listening')return;let text='',finalText='';for(let i=e.resultIndex;i<e.results.length;i++){text+=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=e.results[i][0].transcript}let el=document.getElementById('liveTranscript');if(el)el.textContent=text||'我在听…';if(finalText&&!finalized){finalized=true;handleVoiceCommandV4(finalText,sessionId)}};r.onerror=e=>{experienceCtx.recognitionActive=false;if(e.error!=='aborted'&&experienceCtx.sessionId===sessionId&&!experienceCtx.cancelled)showMicErrorV4(e.error==='not-allowed'?'permission':'recognition')};r.onend=()=>{if(experienceCtx.sessionId!==sessionId||experienceCtx.cancelled)return;experienceCtx.recognitionActive=false;if(!finalized&&experienceCtx.phase==='listening'){let zone=document.getElementById('voiceSessionZone');if(zone)zone.innerHTML=`<div class="permissionHelp"><b>这次没有听清</b><br>你可以重新开始，Claw 不会在未确认时执行任何任务。<div class="voiceConfirmActions"><button class="secondary" onclick="continueVoiceCapture()">${uiIcon('mic')}重新说</button></div></div>`}};r.start()}catch(e){if(experienceCtx.sessionId===sessionId&&!experienceCtx.cancelled)showMicErrorV4(e.message==='secure'?'secure':e.message==='unsupported'?'unsupported':'permission')}}
function handleVoiceCommandV4(text,sessionId=experienceCtx.sessionId){if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId||experienceCtx.committed)return;let cleaned=(text||'').trim();if(!cleaned)return;experienceCtx.transcript=[experienceCtx.transcript,cleaned].filter(Boolean).join('，');experienceCtx.phase='awaitingConfirm';experienceCtx.awaitingConfirm=true;try{if(experienceCtx.recognition){experienceCtx.recognition.onend=null;experienceCtx.recognition.stop()}}catch(e){}renderVoiceConfirmation()}
function renderVoiceConfirmation(){let zone=document.getElementById('voiceSessionZone'),chip=document.getElementById('voiceStateChip');if(chip)chip.innerHTML=`${uiIcon('check')}等待确认`;if(!zone)return;zone.innerHTML=`<section class="voiceConfirmCard"><div class="heardHeader"><span class="heardIcon">${uiIcon('check')}</span><span>我听到了这些内容</span></div><div class="heardText">“${escapeHtml(experienceCtx.transcript)}”</div><div class="confirmHint"><span>如果还有内容，可以继续补充；确认后才开始任务编排。</span><span>不会自动执行</span></div><div class="voiceConfirmActions"><button class="secondary" onclick="continueVoiceCapture()">${uiIcon('mic')}继续说</button><button class="primary confirmPrimary" id="voiceConfirmButton" onclick="confirmVoiceComplete()">${uiIcon('check')}确认说完了</button></div><div class="confirmGuard">此确认只代表语音输入结束；支付及高风险操作仍会单独确认。</div></section>`}
function continueVoiceCapture(){if(experienceCtx.cancelled||experienceCtx.committed)return;experienceCtx.phase='listening';experienceCtx.awaitingConfirm=false;let zone=document.getElementById('voiceSessionZone'),chip=document.getElementById('voiceStateChip');if(chip)chip.innerHTML=`${uiIcon('mic')}正在聆听`;if(zone)zone.innerHTML=voiceCaptureMarkup(experienceCtx.transcript);beginVoiceCaptureV4(experienceCtx.sessionId)}
function confirmVoiceComplete(){if(experienceCtx.cancelled||experienceCtx.committed||experienceCtx.phase!=='awaitingConfirm'||!experienceCtx.transcript)return;experienceCtx.committed=true;experienceCtx.awaitingConfirm=false;experienceCtx.phase='executing';try{if(experienceCtx.recognition){experienceCtx.recognition.onend=null;experienceCtx.recognition.abort()}}catch(e){}experienceCtx.tasks=buildAgentTasks(experienceCtx.tab,experienceCtx.skill,experienceCtx.transcript);renderAgentBoardV4();runAgentTasksV4(experienceCtx.sessionId)}
