function funResultMarkup(skill,text){if(skill==='测测')return `<section class="funResult"><div class="funResultHead"><span class="funResultIcon">${uiIcon('zodiac')}</span><div><h3>自由探索型旅行搭子</h3><small>你的专属画像已生成</small></div></div><p>${escapeHtml(text)}</p><div class="resultTags"><span>好奇心强</span><span>松弛随性</span><span>幸运方向 · 西南</span></div></section>`;if(skill==='神算子')return `<section class="funResult"><div class="funResultHead"><span class="funResultIcon">${uiIcon('fortune')}</span><div><h3>今日签 · 从容</h3><small>轻松娱乐，不作严肃预测</small></div></div><p>${escapeHtml(text)}</p><div class="resultTags"><span>幸运色 · 琥珀橙</span><span>幸运方向 · 东南</span><span>宜提前出发</span></div></section>`;return''}
