function showMicErrorV4(type){let copy=type==='secure'?'请通过 HTTPS 页面打开 Demo，才能使用车内语音体验。':type==='unsupported'?'当前浏览器没有语音识别能力，请使用最新版 Chrome 或 Edge。':'麦克风权限未开启。请在地址栏的网站权限中允许麦克风，然后重新进入体验。',zone=document.getElementById('voiceSessionZone');if(zone)zone.innerHTML=`<div class="permissionHelp"><b>暂时无法开始语音体验</b><br>${copy}<div class="voiceConfirmActions"><button class="secondary" onclick="continueVoiceCapture()">${uiIcon('mic')}重新尝试</button></div></div>`}
function cleanupVoiceExperienceV4(){experienceCtx.cancelled=true;experienceCtx.phase='cancelled';(experienceCtx.timers||[]).forEach(clearTimeout);try{if(experienceCtx.recognition){experienceCtx.recognition.onend=null;experienceCtx.recognition.onresult=null;experienceCtx.recognition.onerror=null;experienceCtx.recognition.abort()}}catch(e){}try{speechSynthesis.cancel()}catch(e){}}
