function startSceneVoiceSession(id=null,mode='create'){if(!S.loggedIn){pendingTask=()=>startSceneVoiceSession(id,mode);loginFlow(mode==='create'?'登录后即可用语音创建并同步我的场景。':'登录后即可恢复并语音调整这个场景。');return}cleanupDemoPlayer();cleanupVoiceExperience();cleanupSceneVoice();let existing=id?S.services.find(x=>x.id===id):null;if(mode==='edit'&&(!existing||existing.source!=='我的场景'))return;if(existing&&existing.template)mode='create';let base=existing?JSON.parse(JSON.stringify(existing)):{id:null,name:'我的新场景',desc:'用语音创建的专属主动场景',source:'我的场景',mode:'提醒并执行',enabled:true,requires:[],trigger:'',actions:[],record:'暂无记录'};let sessionId=++sceneEditSequence;sceneEditCtx={id:mode==='edit'?id:null,templateId:existing&&existing.template?existing.id:null,mode,base,preview:null,recognition:null,timers:[],transcript:'',cancelled:false,sessionId,patch:null,before:mode==='edit'?{name:base.name,trigger:base.trigger,actions:[...(base.actions||[])],mode:base.mode}:null,phase:'listening',awaitingConfirm:false,committed:false,applied:false};renderSceneVoiceModal();beginSceneEditCaptureV4(sessionId)}
