function finishSceneEditV4(sessionId){if(sceneEditCtx.cancelled||sceneEditCtx.sessionId!==sessionId||sceneEditCtx.phase!=='executing'||sceneEditCtx.applied)return;sceneEditCtx.applied=true;let el=document.getElementById('sceneEditFinal'),p=sceneEditCtx.preview;if(!el||!p)return;let saved,diffs=[];if(sceneEditCtx.mode==='create'){saved={id:'custom'+Date.now(),name:p.name,desc:'你用语音创建的专属主动场景',source:'我的场景',mode:p.mode||'提醒并执行',enabled:true,requires:sceneRequires(p.actions),trigger:p.trigger,actions:[...p.actions],record:'刚刚 · 已通过语音创建',accent:'#718bff'};S.services.push(saved);diffs=[['触发',saved.trigger],['任务',saved.actions.join(' → ')],['执行',saved.mode]]}else{saved=S.services.find(x=>x.id===sceneEditCtx.id);if(!saved||saved.source!=='我的场景')return;let b=sceneEditCtx.before;saved.name=p.name;saved.trigger=p.trigger;saved.actions=[...p.actions];saved.mode=p.mode;saved.record='刚刚 · 已通过语音修改';if(b.name!==saved.name)diffs.push(['名称',saved.name]);if(b.trigger!==saved.trigger)diffs.push(['触发',saved.trigger]);if(b.actions.join('|')!==saved.actions.join('|'))diffs.push(['任务',saved.actions.join(' → ')]);if(b.mode!==saved.mode)diffs.push(['执行',saved.mode])}localStorage.setItem('icarClawV3',JSON.stringify(S));renderAll();sceneEditCtx.phase='done';let chip=document.getElementById('sceneVoiceStateChip');if(chip)chip.innerHTML=`${uiIcon('check')}已完成`;el.innerHTML=`<div class="sceneDiff">${diffs.map(x=>`<div class="diffRow"><small>${x[0]}</small><b>${escapeHtml(x[1])}</b></div>`).join('')}</div><div class="sceneSaved"><b>${sceneEditCtx.mode==='create'?'已创建并启动':'已修改并保存'}</b><br>新的规则已同步到首页，下次命中条件时自动生效。</div>`;speakText(`${saved.name}${sceneEditCtx.mode==='create'?'已经创建并启动':'已经修改并保存'}。`);toast(sceneEditCtx.mode==='create'?'场景已创建并加入首页':'场景已通过语音修改并保存')}
