/* V4.1：保留未修改的触发维度，并按分句处理新增/删除动作 */
function parseScenePatchV5(text,s={trigger:'',actions:[]}){let p={name:null,trigger:null,addActions:[],removeCategories:[],mode:null,changes:0},name=text.match(/(?:改名为|名称改为|名字改成|叫做|创建一个叫)\s*[“「]?([^，。,.“”」]{2,12})/);if(name){p.name=name[1].trim();p.changes++}let trigger=s.trigger||'',date=text.match(/工作日|周末|每天|周[一二三四五六日天]/),time=text.match(/(?:早上|上午|中午|下午|晚上)?\s*(?:\d{1,2}(?::\d{2}|点(?:半|\d{1,2}分)?)|[一二三四五六七八九十两]{1,3}点半?)/),place=text.match(/公司附近|到公司后?|到家后?|上车后?|下车后?|锁车后?|导航(?:开始|完成)后?/);if(date||time||place){let oldDate=(trigger.match(/工作日|周末|每天|周[一二三四五六日天]/)||[])[0],oldTime=(trigger.match(/(?:早上|上午|中午|下午|晚上)?\s*(?:\d{1,2}(?::\d{2}|点(?:半|\d{1,2}分)?)|[一二三四五六七八九十两]{1,3}点半?)(?:\s*后)?/)||[])[0],oldPlace=(trigger.match(/公司附近|到公司后?|到家后?|本人上车|上车后?|下车后?|锁车后?|导航(?:开始|完成)后?/)||[])[0],parts=[date?date[0]:oldDate,time?time[0].replace(/\s/g,''):oldTime,place?place[0]:oldPlace].filter(Boolean);p.trigger=[...new Set(parts)].join(' · ');p.changes++}let clauses=text.split(/(?:，|。|；|,|;|然后|再)/).map(x=>x.trim()).filter(Boolean),rules=[{cat:'air',re:/空调(?:调到|设为|改到|改成)?\s*(\d{2})(?:度|°C)?/,make:m=>'空调 '+m[1]+'°C'},{cat:'seat',re:/座椅(?:加热|通风)(?:调到|设为)?\s*([一二三123]档)?/,make:m=>'座椅'+(/通风/.test(m[0])?'通风':'加热')+(m[1]||'一档')},{cat:'nav',re:/导航(?:到|去|回)?([^，。,.]{1,10})/,make:m=>'导航'+(m[1]==='家'?'回家':'到'+m[1])},{cat:'media',re:/(?:播放|放|听)(?:一点|点)?([^，。,.]{0,12}(?:音乐|歌|新闻|播客|周杰伦))?/,make:m=>'播放'+(m[1]||'轻松音乐')},{cat:'remind',re:/提醒(?:我)?([^，。,.]{1,14})/,make:m=>'提醒'+m[1]}];clauses.forEach(clause=>{let removing=/不要|取消|去掉|删除/.test(clause);rules.forEach(r=>{let m=clause.match(r.re);if(!m)return;if(removing)p.removeCategories.push(r.cat);else p.addActions.push({cat:r.cat,value:r.make(m)});p.changes++})});if(/只提醒|仅提醒/.test(text)){p.mode='仅提醒';p.changes++}else if(/自动执行|直接执行|提醒并执行/.test(text)){p.mode='提醒并执行';p.changes++}return p}
