function skillProfileV6(tab,skill){let p=SKILL_CATALOG_V6[tab+'|'+skill];if(!p&&skill){let keys=Object.keys(SKILL_CATALOG_V6).filter(k=>k.endsWith('|'+skill));if(keys.length===1)p=SKILL_CATALOG_V6[keys[0]]}if(!p)throw new Error('缺少技能配置：'+tab+' / '+skill);return p}
function userSkillCopyV6(skill,tab=''){if(tab==='全局语音'||(!tab&&experienceCtx.tab==='全局语音'))return'一句话可同时包含导航、车控、内容和生活服务，Claw 会自动拆解并协同完成。';return skillProfileV6(tab||experienceCtx.tab,skill).desc}
