function featureCopyV6(skill,tab=''){if(tab==='全局语音')return[['理解完整需求','识别多个意图与先后关系','sparkles'],['规划任务依赖','选择地图、车控、媒体或服务能力','route'],['连续执行反馈','在同一张卡片中更新每项状态','check']];return skillProfileV6(tab||experienceCtx.tab,skill).features}
function skillIconKeyV6(tab,skill){if(tab==='全局语音')return'sparkles';return skillProfileV6(tab,skill).icon}
function demoFramesV6(tab,skill){let p=skillProfileV6(tab,skill);return[{title:'用户说出需求',detail:'“'+p.example+'”',icon:'mic',chips:p.tags},...p.features.map((x,i)=>({title:x[0],detail:x[1],icon:x[2]||p.icon,chips:[p.tags[i%p.tags.length],p.tags[(i+1)%p.tags.length]].filter(Boolean)})),{title:'完成并反馈',detail:p.result,icon:'check',chips:p.tags}]}
function demoChipMarkupV6(chip){let color=/^#[0-9a-f]{6}$/i.test(chip);return'<span class="demoStoryboardTag">'+(color?'<i style="--chip:'+chip+'"></i>':'')+escapeHtml(chip)+'</span>'}
function resolveAtmosphereV7(text='',full=false){let value=(text||'').toLowerCase(),p={name:full?'海边黄昏':'落日玫瑰',main:'#FF7A59',aux:full?'#7C5CFF':'#8B5CF6',brightness:full?38:32,cycle:full?12:8,sound:full?'海浪环境音 · 轻音乐':'柔和渐变'};if(/赛博|科技|未来|蓝色/.test(value))p={name:'赛博夜航',main:'#45B8FF',aux:'#7C5CFF',brightness:42,cycle:6,sound:'电子氛围 · 低频节拍'};else if(/森林|露营|自然|绿色/.test(value))p={name:'森林呼吸',main:'#47C98A',aux:'#8FD694',brightness:34,cycle:12,sound:'林间环境音 · 木吉他'};else if(/热烈|活力|派对|红色/.test(value))p={name:'热力派对',main:'#FF4D6D',aux:'#FFB347',brightness:55,cycle:4,sound:'律动节拍 · 动态追光'};else if(/海边|松弛|海洋/.test(value))p={name:'海岸松弛',main:'#36C9C6',aux:'#6D7DFF',brightness:38,cycle:12,sound:'海浪环境音 · 轻音乐'};return p}
