function vehicleVisualV7(skill,index,p){let body='',meta='座舱实时状态';if(skill==='感受类控车')body='<div class="vehicleSilhouette"><i class="seat one"></i><i class="seat two"></i><i class="air"></i></div><div class="metricRow"><div class="metric"><small>主驾座椅</small><b>通风 '+(index>2?'二档':'待调整')+'</b></div><div class="metric"><small>出风方向</small><b>'+(index>2?'避开面部':'面部直吹')+'</b></div></div>';else if(skill==='描述类控车')body='<div class="gaugeRow"><div class="gauge"><small>CO₂</small><b>'+(index>2?'760':'1260')+'</b></div><div class="gauge"><small>PM2.5</small><b>'+(index>2?'18':'43')+'</b></div><div class="gauge"><small>空气模式</small><b style="font-size:11px">'+(index>1?'净化中':'内循环')+'</b></div></div>';else if(skill==='其他模糊类车控')body='<div class="roofTrack"><span>天窗起翘 '+(index>2?'15%':'—')+' · 遮阳帘 '+(index>2?'40%':'—')+'</span></div>';else if(skill==='多任务控车')body='<div class="controlRow"><span class="controlChip '+(index>1?'on':'')+'">车窗 ×4</span><span class="controlChip '+(index>2?'on':'')+'">空调 24°C</span><span class="controlChip '+(index>3?'on':'')+'">座椅通风 2</span></div>';else{let c=resolveAtmosphereV7(p.example);body='<div class="vehicleSilhouette lightCabin" style="--main:'+c.main+';--aux:'+c.aux+'"><i class="seat one"></i><i class="seat two"></i><i class="air"></i></div><div class="metricRow"><div class="metric"><small>主色</small><b>'+c.main+'</b></div><div class="metric"><small>亮度</small><b>'+c.brightness+'%</b></div></div>';meta=c.name}return[body,meta]}
function travelVisualV7(skill,index){let body='',meta='路线正在生成';if(skill==='多日行程规划')body='<div class="dayPlan"><em>周六</em><span>东湖骑行 · 湖北菜 · 江景酒店</span><em>周日</em><span>美术馆 · 老街午餐 · 返程</span></div>';else if(skill==='生活搜索')body='<div class="searchTiles"><div class="searchTile">'+uiIcon('service')+'<b>长辈友好餐厅</b></div><div class="searchTile">'+uiIcon('home')+'<b>附近酒店</b></div><div class="searchTile">'+uiIcon('route')+'<b>轻松景点</b></div></div>';else if(skill==='模糊POI搜索')body='<div class="searchTiles"><div class="searchTile">'+uiIcon('eye')+'<b>红砖建筑</b></div><div class="searchTile">'+uiIcon('leaf')+'<b>大草坪</b></div><div class="searchTile">'+uiIcon('service')+'<b>可以喝咖啡</b></div></div>';else{let common=skill==='常用地直达';body='<div class="miniMap"><i class="routeLine"></i><i class="mapPin a"></i><i class="mapPin b"></i><span class="mapLabel a">'+(common?'女儿学校':'车辆入口')+'</span><span class="mapLabel b">'+(common?'家 · 预计 19:12':'急诊落客点')+'</span></div>';meta=common?'两站路线':'最后 100 米'}return[body,meta]}
