function showSkillDemoV9(tab,skill){if(!isAvailableSkillV12(tab,skill)){toast('该技能已更新，请返回首页重新选择');return}cleanupDemoPlayerV7();let p=skillProfileV6(tab,skill),frames=demoFramesV7(tab,skill),sessionId=++demoSequenceV7;demoPlayerCtx={timer:null,timeouts:[],frames,index:0,elapsed:0,running:false,tab,skill,accent:p.accent,sessionId,playbackState:'ready'};let group=p.group?` · ${p.group}`:'';modal(`<section class="detailMediaShell"><header class="detailMediaHeader"><div class="detailMediaTitle"><div class="eyebrow">${escapeHtml(tab+group)}</div><h2>${escapeHtml(skill)}</h2><p>${escapeHtml(p.desc)}</p></div>${modalCloseButton()}</header><div class="detailMediaCinema"><div class="skillDemoPlayer" style="--demoAccent:${p.accent}"><div class="demoPlayerTop"><span class="demoPlayerBadge">${uiIcon('play')}场景演示</span><span id="demoTime">00:00</span></div><div class="demoStage"><div class="demoStageInner" id="demoStageInner"></div></div><div class="demoControls"><button class="demoPlay" id="demoPlayBtn" onclick="toggleDemoPlayback()" aria-label="播放演示">${uiIcon('play')}</button><div class="demoProgress"><i id="demoProgressBar"></i></div><span class="demoCounterLabel" id="demoCounter">准备播放</span></div></div></div><footer class="detailMediaFooter"><span>${uiIcon('sparkles')}动画用于快速了解能力，执行过程会在语音体验中动态呈现。</span><div class="actions"><button class="ghost" onclick="closeModal()">返回</button><button class="primary" data-tab="${escapeHtml(tab)}" data-skill="${escapeHtml(skill)}" onclick="startSkillExperience(this.dataset.tab,this.dataset.skill)">${uiIcon('mic')}立即语音体验</button></div></footer></section>`,'detailMediaModal');renderDemoFrameV9(0,sessionId);let timer=setTimeout(()=>{if(demoPlayerCtx.sessionId===sessionId&&demoPlayerCtx.playbackState==='ready')startDemoPlayback()},260);demoPlayerCtx.timeouts.push(timer)}
