/* V9：系统场景视频详情；我的场景先查看再编辑 */
function renderHomeSceneListV9(list,empty){return list.map(s=>{let m=depStatus(s),custom=s.source==='我的场景';return `<div class="compactService ${custom?'customScene':''}" onclick="openScene('${s.id}')"><span class="icon">${uiIcon(sceneIconKey(s))}</span><span><b>${escapeHtml(s.name)}</b><small>${m.length?'需要开启 '+m.join('、'):escapeHtml(s.desc)}</small><span class="sceneType">${custom?'我的场景 · 查看详情':'系统预置 · 查看详情'}</span></span><button class="quickOff" onclick="event.stopPropagation();quickCloseScene('${s.id}')" aria-label="关闭${escapeHtml(s.name)}">${uiIcon('close')}</button></div>`}).join('')||`<div class="emptyScene">${empty}</div>`}
function serviceCardV9(s){let m=depStatus(s),official=s.source==='iCAR 官方';return `<div class="service"><div class="cardTop"><span class="icon">${uiIcon(sceneIconKey(s))}</span><span class="badge ${m.length?'warn':s.enabled?'ok':''}">${s.template?'场景模板':m.length?'待开启':s.enabled?'已开启':'已关闭'}</span></div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.desc)}</p><div class="statusline"><span class="badge">${uiIcon(official?'lock':'user','sm')}${official?'系统预置':s.template?'语音创建':'我的场景'}</span>${m.length?`<span class="badge warn">开启 ${m.join('、')}</span>`:''}</div><div class="serviceFoot"><button class="link" onclick="openScene('${s.id}')">${official?'查看详情':s.template?'查看并创建':'查看详情'}</button>${s.template?'':`<button class="switch ${s.enabled?'on':''}" onclick="event.stopPropagation();toggleService('${s.id}')"><i></i></button>`}</div></div>`}
function renderServicesV9(){let visible=S.services.filter(x=>!x.legacyHidden),act=visible.filter(x=>x.enabled),rec=visible.filter(x=>!x.enabled);document.getElementById('activeServices').innerHTML=act.map(serviceCardV9).join('')||'<p class="sub">暂无已开启服务</p>';document.getElementById('recommendations').innerHTML=rec.map(serviceCardV9).join('')+`<div class="service"><div class="cardTop"><span class="icon">${uiIcon('sparkles')}</span><span class="badge">习惯建议</span></div><h3>下班音乐习惯</h3><p>最近 5 次下班上车，你都会调至 24°C 并播放周杰伦。</p><div class="serviceFoot"><button class="link" onclick="habitFlow()">查看推荐依据</button></div></div>`;let mine=S.loggedIn?visible.filter(x=>x.source==='我的场景'&&!x.template):[];document.getElementById('myScenes').innerHTML=mine.map(serviceCardV9).join('');document.getElementById('myScenesBlock').classList.toggle('hidden',!S.loggedIn);let notes=[];if(!S.memoryOn)notes.push('我的记忆已关闭：个性化温度、路线与音乐推荐将降级');if(!S.cabinEnv)notes.push('座舱环境感知已关闭：空气质量守护无法判断触发条件');if(!S.outside)notes.push('车外感知已关闭：哨兵、停车和找车能力受限');document.getElementById('serviceNotice').innerHTML=notes.map(x=>`<div class="notice">${x}</div>`).join('')}
function sceneDetailHeaderV9(s,type){return `<header class="detailMediaHeader"><div class="detailMediaTitle"><div class="eyebrow">${uiIcon(type==='系统预置'?'lock':'user','sm')}${type} · <span class="sceneStatusDot ${s.enabled?'':'off'}">${s.enabled?'已开启':'已关闭'}</span></div><h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.desc)}</p></div>${modalCloseButton()}</header>`}
function sceneVideoMarkupV9(s){return `<div class="sceneDetailVideo" id="sceneDetailVideo" style="--sceneAccent:${s.accent||'#718bff'}"><div class="sceneDetailArt"><div class="sceneVideoOverlay"><i></i>场景演示</div>${sceneArtMarkup(s)}<div class="sceneVideoCaption"><b>${escapeHtml(s.name)}</b><span>${escapeHtml(s.desc)}</span></div></div><div class="sceneVideoControls"><button class="ghost" id="sceneVideoPlay" onclick="toggleSceneVideoV9()" aria-label="播放或暂停">${uiIcon('pause')}</button><div class="sceneVideoProgress"><i></i></div><span class="demoCounterLabel">动态演示</span></div></div>`}
function toggleSceneVideoV9(){let frame=document.getElementById('sceneDetailVideo'),btn=document.getElementById('sceneVideoPlay');if(!frame||!btn)return;let paused=frame.classList.toggle('paused');btn.innerHTML=uiIcon(paused?'play':'pause')}
function mySceneSummaryV9(s){return `<div class="mySceneSummary"><section class="mySceneRuleHero" style="--sceneAccent:${s.accent||'#718bff'}">${sceneArtMarkup(s)}<div><span class="badge">${s.template?'创建模板':'我的规则'}</span><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.desc)}</p></div></section><section class="mySceneRuleList"><div class="ruleSummaryItem"><small>${uiIcon('route','sm')}触发条件</small><b>${escapeHtml(s.trigger||'等待语音描述')}</b></div><div class="ruleSummaryItem"><small>${uiIcon('sparkles','sm')}执行内容</small><div class="ruleActionChips">${(s.actions||[]).map(a=>`<span>${escapeHtml(a)}</span>`).join('')||'<span>等待语音描述</span>'}</div></div><div class="ruleSummaryItem"><small>${uiIcon('shield','sm')}执行方式与记录</small><b>${escapeHtml(s.mode||'提醒并执行')} · ${escapeHtml(s.record||'暂无执行记录')}</b></div></section></div>`}
function openSceneV9(id){cleanupDemoPlayer();cleanupVoiceExperience();cleanupSceneVoice();let s=S.services.find(x=>x.id===id);if(!s)return;if(s.source==='iCAR 官方'){let miss=depStatus(s),primary=!s.enabled&&miss.length?`<button class="primary" onclick="goSceneDependencyV9('${s.id}')">${uiIcon('settings')}去开启权限</button>`:`<button class="primary" onclick="toggleSceneFromDetailV9('${s.id}')">${s.enabled?'关闭场景':'开启场景'}</button>`;modal(`<section class="detailMediaShell">${sceneDetailHeaderV9(s,'系统预置')}<div class="detailMediaCinema">${sceneVideoMarkupV9(s)}</div><footer class="detailMediaFooter"><span class="sceneReadOnlyLine">${uiIcon('lock')}由 iCAR 维护，触发规则不可编辑。</span><div class="actions"><button class="ghost" onclick="closeModal()">返回</button>${primary}</div></footer></section>`,'sceneDetailModal');return}let type=s.template?'我的场景模板':'我的场景',main=s.template?`<button class="primary" onclick="startSceneVoiceSession('${s.id}','create')">${uiIcon('mic')}用语音创建</button>`:`<button class="primary" onclick="editMySceneV9('${s.id}')">${uiIcon('edit')}编辑场景</button>`,toggle=s.template?'':`<button class="secondary" onclick="toggleSceneFromDetailV9('${s.id}')">${s.enabled?'关闭场景':'开启场景'}</button>`;modal(`<section class="detailMediaShell">${sceneDetailHeaderV9(s,type)}<div class="detailMediaCinema">${mySceneSummaryV9(s)}</div><footer class="detailMediaFooter"><span>${uiIcon('shield')}只有点击“编辑场景”后，才会进入语音修改流程。</span><div class="actions"><button class="ghost" onclick="closeModal()">返回</button>${toggle}${main}</div></footer></section>`,'sceneDetailModal')}
function editMySceneV9(id){let s=S.services.find(x=>x.id===id);if(!s||s.source!=='我的场景'||s.template){toast('系统预置与场景模板不支持直接编辑');return}startSceneVoiceSession(id,'edit')}
function toggleSceneFromDetailV9(id){toggleService(id);closeModal()}
function goSceneDependencyV9(id){let s=S.services.find(x=>x.id===id);closeModal();openSettings('privacy');toast(`${s?s.name:'这个场景'}需要先开启相关权限`)}

/* V9：新建/编辑场景的重复、相似与互斥检查 */
function normalizeSceneTextV9(value=''){return String(value).toLowerCase().replace(/导航到家|导航去家|回家导航/g,'导航回家').replace(/打开/g,'开启').replace(/关掉/g,'关闭').replace(/摄氏度|度/g,'c').replace(/\s|[·，。,.;；：:“”「」『』（）()\-_/]/g,'')}
function sceneTokensV9(value=''){let s=normalizeSceneTextV9(value),tokens=new Set;if(!s)return tokens;for(let i=0;i<s.length;i++){tokens.add(s[i]);if(i<s.length-1)tokens.add(s.slice(i,i+2))}return tokens}
function jaccardV9(a,b){let aa=sceneTokensV9(a),bb=sceneTokensV9(b);if(!aa.size&&!bb.size)return 1;if(!aa.size||!bb.size)return 0;let hit=0;aa.forEach(x=>{if(bb.has(x))hit++});return hit/(aa.size+bb.size-hit)}
function actionCategoryV9(action=''){let a=String(action);if(/空调|温度|内循环|外循环|净化|除雾|雨刷|后视镜加热/.test(a))return'climate';if(/座椅/.test(a))return'seat';if(/导航|路线|停车/.test(a))return'route';if(/播放|音乐|歌曲|新闻|播客|内容/.test(a))return'media';if(/提醒|通知|播报|问候|介绍/.test(a))return'notice';if(/车窗|车门|后备箱/.test(a))return'body';return normalizeSceneTextV9(a).slice(0,8)||'other'}
function normalizedActionSetV9(scene){return new Set((scene.actions||[]).map(normalizeSceneTextV9).filter(Boolean))}
function categorySetV9(scene){return new Set((scene.actions||[]).map(actionCategoryV9))}
function setOverlapV9(a,b){if(!a.size&&!b.size)return 1;if(!a.size||!b.size)return 0;let hit=0;a.forEach(x=>{if(b.has(x))hit++});return hit/Math.max(a.size,b.size)}
function actionsConflictV9(a,b){for(let left of(a.actions||[]))for(let right of(b.actions||[])){if(actionCategoryV9(left)!==actionCategoryV9(right))continue;let l=normalizeSceneTextV9(left),r=normalizeSceneTextV9(right),ln=(l.match(/\d{2}/)||[])[0],rn=(r.match(/\d{2}/)||[])[0];if(ln&&rn&&ln!==rn)return true;if((/开启/.test(l)&&/关闭/.test(r))||(/关闭/.test(l)&&/开启/.test(r)))return true;if((/加热/.test(l)&&/通风/.test(r))||(/通风/.test(l)&&/加热/.test(r)))return true;if(actionCategoryV9(left)==='route'&&l!==r&&/导航/.test(l)&&/导航/.test(r))return true}return false}
function sceneSimilarityV9(candidate,existing){let triggerA=normalizeSceneTextV9(candidate.trigger),triggerB=normalizeSceneTextV9(existing.trigger),triggerExact=!!triggerA&&triggerA===triggerB,triggerScore=jaccardV9(candidate.trigger,existing.trigger),actionsA=normalizedActionSetV9(candidate),actionsB=normalizedActionSetV9(existing),actionOverlap=setOverlapV9(actionsA,actionsB),catsA=categorySetV9(candidate),catsB=categorySetV9(existing),categoryOverlap=setOverlapV9(catsA,catsB),actionsExact=actionsA.size===actionsB.size&&actionOverlap===1,modeExact=normalizeSceneTextV9(candidate.mode||'提醒并执行')===normalizeSceneTextV9(existing.mode||'提醒并执行'),nameScore=jaccardV9(candidate.name,existing.name),exact=triggerExact&&actionsExact&&modeExact,conflict=!exact&&triggerScore>=.78&&actionsConflictV9(candidate,existing),score=triggerScore*.5+Math.max(actionOverlap,categoryOverlap*.86)*.4+nameScore*.1,similar=!exact&&!conflict&&((triggerScore>=.58&&Math.max(actionOverlap,categoryOverlap)>=.5)||score>=.72);let reasons=[];if(triggerExact)reasons.push('触发条件一致');else if(triggerScore>=.58)reasons.push('触发条件相近');if(actionsExact)reasons.push('执行内容一致');else if(actionOverlap>=.5||categoryOverlap>=.5)reasons.push('执行内容有重合');if(conflict)reasons.push('同一时机存在互斥动作');return{exact,conflict,similar,score,reasons}}
function findSceneMatchesV9(candidate,excludeId=null){let rank={exact:0,conflict:1,similar:2},matches=[];S.services.filter(s=>!s.legacyHidden&&!s.template&&s.id!==excludeId).forEach(scene=>{let result=sceneSimilarityV9(candidate,scene),level=result.exact?'exact':result.conflict?'conflict':result.similar?'similar':'';if(level)matches.push({scene,level,score:result.score,reasons:result.reasons,scope:scene.source==='iCAR 官方'?'official':'mine'})});return matches.sort((a,b)=>rank[a.level]-rank[b.level]||b.score-a.score||(a.scope==='official'?-1:1)).slice(0,3)}
function renderSceneAgentBoardV9(){let creating=sceneEditCtx.mode==='create',tasks=creating?[['理解场景描述','识别触发条件、任务与执行方式'],['检查系统预置','查找一致、相似或可能冲突的官方场景'],['检查我的场景','避免重复创建，并判断是否更适合合并'],['生成场景规则','形成可执行规则并核对所需权限'],['创建并同步','确认后绑定当前车主账号并展示到首页']]:[['理解修改内容','识别时间、地点、动作与执行方式'],['对照当前规则','只更新你明确提到的内容'],['检查系统与我的场景','排除重复、相似和互斥执行'],['更新并同步','保存规则并实时刷新首页']];sceneEditCtx.tasks=tasks;modal(`<div class="idealVoiceShell">${idealSceneHeader(creating?'创建我的场景':`调整「${sceneEditCtx.base.name}」`,'正在执行')}<main class="idealVoiceCanvas">${sceneVoiceContextMarkup()}<div class="agentBoard v4"><aside class="agentSummary"><span class="agentSummaryIcon">${uiIcon(creating?'plus':'edit')}</span><small>已确认的语音</small><p>“${escapeHtml(sceneEditCtx.transcript)}”</p></aside><div><div class="taskFlow">${tasks.map((t,i)=>`<div class="agentTask" id="sceneTask${i}"><span class="taskDot"></span><span><b>${t[0]}</b><span>${t[1]}</span></span><em>等待</em></div>`).join('')}</div><div id="sceneEditFinal"></div></div></div></main></div>`,'sceneVoiceModal')}
function sceneMatchTitleV9(match){if(match.level==='exact')return match.scope==='official'?'已有可用的系统场景':'你已经有相同场景';if(match.level==='conflict')return'发现可能同时触发的场景';return match.scope==='official'?'发现相似的系统场景':'发现相似的我的场景'}
function sceneMatchCopyV9(match){if(match.level==='exact')return match.scope==='official'?`“${match.scene.name}”与本次需求一致，无需重复创建。`:`“${match.scene.name}”与本次需求一致，可直接查看或编辑已有场景。`;if(match.level==='conflict')return`“${match.scene.name}”在相近条件下执行不同操作，建议先调整，避免双重执行。`;return`“${match.scene.name}”与本次需求有较多相同点，你可以使用已有场景，或保留差异继续创建。`}
function sceneMatchButtonsV9(match){let id=match.scene.id;if(match.level==='exact'&&match.scope==='official')return `<button class="ghost" onclick="restartSceneVoiceV9(true)">重新描述</button><button class="secondary" onclick="viewSceneMatchV9('${id}')">查看已有</button>${match.scene.enabled?'<button class="primary" disabled>已开启</button>':`<button class="primary" onclick="resolveSceneMatchV9('enable','${id}')">直接开启</button>`}`;if(match.level==='exact')return `<button class="ghost" onclick="restartSceneVoiceV9(true)">重新描述</button><button class="secondary" onclick="viewSceneMatchV9('${id}')">查看已有</button><button class="primary" onclick="resolveSceneMatchV9('edit','${id}')">编辑已有</button>`;if(match.level==='conflict')return `<button class="ghost" onclick="restartSceneVoiceV9(false)">调整新场景</button><button class="primary" onclick="resolveSceneMatchV9('${match.scope==='mine'?'edit':'view'}','${id}')">${match.scope==='mine'?'编辑已有':'查看系统场景'}</button>`;if(match.scope==='official')return `<button class="ghost" onclick="resolveSceneMatchV9('force','${id}')">继续创建我的场景</button><button class="secondary" onclick="viewSceneMatchV9('${id}')">查看系统场景</button><button class="primary" onclick="resolveSceneMatchV9('enable','${id}')">使用并开启</button>`;return `<button class="ghost" onclick="resolveSceneMatchV9('force','${id}')">仍然新建</button><button class="secondary" onclick="viewSceneMatchV9('${id}')">查看已有</button><button class="primary" onclick="showMergePreviewV9('${id}')">合并到已有</button>`}
function sceneMatchPanelV9(matches){let first=matches[0];return `<section class="sceneMatchPanel"><header><span class="icon">${uiIcon(first.level==='conflict'?'warning':first.level==='exact'?'check':'sparkles')}</span><div><h3>${sceneMatchTitleV9(first)}</h3><p>${sceneMatchCopyV9(first)}</p></div></header>${matches.map((m,i)=>`<article class="sceneMatchCard"><div class="sceneMatchCardTop"><div><h4>${escapeHtml(m.scene.name)}</h4><p>${m.scope==='official'?'系统预置 · 不可编辑':'我的场景'} · ${m.scene.enabled?'已开启':'已关闭'}</p></div><span class="badge ${m.level==='conflict'?'warn':m.level==='exact'?'ok':''}">${m.level==='exact'?'一致':m.level==='conflict'?'可能冲突':'相似'}</span></div><div class="sceneMatchReason">${m.reasons.map(r=>`<span>${escapeHtml(r)}</span>`).join('')}</div>${i===0?`<div class="sceneMatchActions">${sceneMatchButtonsV9(m)}</div>`:''}</article>`).join('')}</section>`}
function renderSceneMatchShellV9(){modal(`<div class="idealVoiceShell">${idealSceneHeader(sceneEditCtx.mode==='create'?'创建我的场景':`调整「${sceneEditCtx.base.name}」`,'等待选择')}<main class="idealVoiceCanvas">${sceneVoiceContextMarkup()}${sceneMatchPanelV9(sceneEditCtx.matches||[])}</main></div>`,'sceneVoiceModal')}
function renderSceneReadyV9(){let p=sceneEditCtx.preview,el=document.getElementById('sceneEditFinal');sceneEditCtx.phase='ready';if(!el)return;el.innerHTML=`<section class="sceneMatchPanel"><header><span class="icon">${uiIcon('check')}</span><div><h3>检查完成，可以创建</h3><p>未发现重复、相似或互斥场景。确认后将创建并立即开启。</p></div></header><div class="sceneMatchCard"><h4>${escapeHtml(p.name)}</h4><p>${escapeHtml(p.trigger)} · ${(p.actions||[]).map(escapeHtml).join(' → ')}</p><div class="sceneMatchReason"><span>未发现重复场景</span><span>${escapeHtml(p.mode||'提醒并执行')}</span></div><div class="sceneMatchActions"><button class="ghost" onclick="restartSceneVoiceV9(false)">返回调整</button><button class="primary" onclick="confirmCreateSceneV9()">确认创建并开启</button></div></div></section>`;let chip=document.getElementById('sceneVoiceStateChip');if(chip)chip.innerHTML=`${uiIcon('check')}等待创建`}
function finishSceneEditV9(sessionId){if(sceneEditCtx.cancelled||sceneEditCtx.sessionId!==sessionId||sceneEditCtx.phase!=='executing'||sceneEditCtx.applied)return;let el=document.getElementById('sceneEditFinal'),p=sceneEditCtx.preview;if(!el||!p)return;if(sceneEditCtx.mode==='edit'){commitEditedSceneV9();return}let matches=findSceneMatchesV9(p,null);sceneEditCtx.matches=matches;if(matches.length){sceneEditCtx.phase='decision';let chip=document.getElementById('sceneVoiceStateChip');if(chip)chip.innerHTML=`${uiIcon(matches[0].level==='conflict'?'warning':'sparkles')}等待选择`;el.innerHTML=sceneMatchPanelV9(matches);return}renderSceneReadyV9()}
function renderSceneCompletedV9(saved,creating,diffs=[]){sceneEditCtx.phase='done';sceneEditCtx.applied=true;let chip=document.getElementById('sceneVoiceStateChip'),el=document.getElementById('sceneEditFinal');if(chip)chip.innerHTML=`${uiIcon('check')}已完成`;if(el)el.innerHTML=`<div class="sceneDiff">${diffs.map(x=>`<div class="diffRow"><small>${x[0]}</small><b>${escapeHtml(x[1])}</b></div>`).join('')}</div><div class="sceneSaved"><b>${creating?'已创建并启动':'已修改并保存'}</b><br>新的规则已同步到首页，下次命中条件时自动生效。</div>`;speakText(`${saved.name}${creating?'已经创建并启动':'已经修改并保存'}。`);toast(creating?'场景已创建并加入首页':'场景已通过语音修改并保存')}
function commitSceneDraftV9(){if(sceneEditCtx.resolutionCommitted||sceneEditCtx.applied)return;sceneEditCtx.resolutionCommitted=true;let p=sceneEditCtx.preview,saved={id:'custom'+Date.now(),name:p.name,desc:'你用语音创建的专属主动场景',source:'我的场景',mode:p.mode||'提醒并执行',enabled:true,requires:sceneRequires(p.actions),trigger:p.trigger,actions:[...p.actions],record:'刚刚 · 已通过语音创建',accent:'#718bff'};S.services.push(saved);localStorage.setItem('icarClawV3',JSON.stringify(S));renderAll();renderSceneCompletedV9(saved,true,[['触发',saved.trigger],['任务',saved.actions.join(' → ')],['执行',saved.mode]])}
function confirmCreateSceneV9(){if(sceneEditCtx.phase!=='ready')return;let matches=findSceneMatchesV9(sceneEditCtx.preview,null);if(matches.length){sceneEditCtx.matches=matches;sceneEditCtx.phase='decision';renderSceneMatchShellV9();return}commitSceneDraftV9()}
function commitEditedSceneV9(){if(sceneEditCtx.applied)return;let saved=S.services.find(x=>x.id===sceneEditCtx.id);if(!saved||saved.source!=='我的场景')return;let p=sceneEditCtx.preview,b=sceneEditCtx.before,diffs=[];saved.name=p.name;saved.trigger=p.trigger;saved.actions=[...p.actions];saved.mode=p.mode;saved.requires=sceneRequires(saved.actions);saved.record='刚刚 · 已通过语音修改';if(b.name!==saved.name)diffs.push(['名称',saved.name]);if(b.trigger!==saved.trigger)diffs.push(['触发',saved.trigger]);if(b.actions.join('|')!==saved.actions.join('|'))diffs.push(['任务',saved.actions.join(' → ')]);if(b.mode!==saved.mode)diffs.push(['执行',saved.mode]);localStorage.setItem('icarClawV3',JSON.stringify(S));renderAll();renderSceneCompletedV9(saved,false,diffs)}
function restartSceneVoiceV9(clear=false){sceneEditCtx.committed=false;sceneEditCtx.applied=false;sceneEditCtx.resolutionCommitted=false;sceneEditCtx.phase='listening';sceneEditCtx.awaitingConfirm=false;sceneEditCtx.matches=[];sceneEditCtx.patch=null;sceneEditCtx.preview=null;if(clear)sceneEditCtx.transcript='';renderSceneVoiceModal();beginSceneEditCaptureV4(sceneEditCtx.sessionId)}
function viewSceneMatchV9(id){let s=S.services.find(x=>x.id===id);if(!s)return;let middle=s.source==='iCAR 官方'?sceneVideoMarkupV9(s):mySceneSummaryV9(s);modal(`<section class="detailMediaShell">${sceneDetailHeaderV9(s,s.source==='iCAR 官方'?'系统预置':'我的场景')}<div class="detailMediaCinema">${middle}</div><footer class="detailMediaFooter"><span>${uiIcon('shield')}新场景草稿与检查结果已保留。</span><div class="actions"><button class="primary" onclick="renderSceneMatchShellV9()">返回检查结果</button></div></footer></section>`,'sceneDetailModal')}
function renderSceneResolutionV9(title,copy){sceneEditCtx.phase='done';sceneEditCtx.applied=true;modal(`<div class="idealVoiceShell">${idealSceneHeader('创建我的场景','已完成')}<main class="idealVoiceCanvas">${sceneVoiceContextMarkup()}<section class="sceneMatchPanel"><header><span class="icon">${uiIcon('check')}</span><div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(copy)}</p></div></header><div class="sceneMatchActions"><button class="primary" onclick="closeModal()">完成</button></div></section></main></div>`,'sceneVoiceModal')}
function resolveSceneMatchV9(action,id){if(sceneEditCtx.resolutionCommitted)return;let target=S.services.find(x=>x.id===id);if(!target)return;if(action==='view'){viewSceneMatchV9(id);return}if(action==='edit'){startSceneVoiceSession(id,'edit');return}if(action==='force'){sceneEditCtx.phase='ready';commitSceneDraftV9();return}if(action==='enable'){sceneEditCtx.resolutionCommitted=true;target.enabled=true;localStorage.setItem('icarClawV3',JSON.stringify(S));renderAll();renderSceneResolutionV9(`已使用“${target.name}”`,target.source==='iCAR 官方'?'系统场景已开启，没有重复创建。':'已有场景已开启，没有重复创建。');toast(`${target.name}已开启`)}}
function mergeActionsV9(target,candidate){let result=[...(target.actions||[])],replaced=[],added=[];(candidate.actions||[]).forEach(action=>{let cat=actionCategoryV9(action),same=result.findIndex(x=>actionCategoryV9(x)===cat);if(result.some(x=>normalizeSceneTextV9(x)===normalizeSceneTextV9(action)))return;if(same>=0){replaced.push(`${result[same]} → ${action}`);result[same]=action}else{result.push(action);added.push(action)}});return{actions:[...new Set(result)],replaced,added,kept:(target.actions||[]).filter(x=>!replaced.some(r=>r.startsWith(x+' → ')))}}
function showMergePreviewV9(id){let target=S.services.find(x=>x.id===id);if(!target||target.source!=='我的场景')return;let plan=mergeActionsV9(target,sceneEditCtx.preview);sceneEditCtx.mergeTarget=id;sceneEditCtx.mergePlan=plan;modal(`<div class="idealVoiceShell">${idealSceneHeader(`合并到「${target.name}」`,'等待确认')}<main class="idealVoiceCanvas"><section class="sceneMatchPanel"><header><span class="icon">${uiIcon('sparkles')}</span><div><h3>确认合并内容</h3><p>保留已有触发条件“${escapeHtml(target.trigger)}”；只合并执行内容，避免静默扩大触发范围。</p></div></header><div class="mergeGrid"><div><small>保留</small><b>${plan.kept.map(escapeHtml).join('、')||'保留原场景名称与触发条件'}</b></div><div><small>新增</small><b>${plan.added.map(escapeHtml).join('、')||'无新增动作'}</b></div><div><small>替换</small><b>${plan.replaced.map(escapeHtml).join('、')||'无冲突替换'}</b></div></div><div class="sceneMatchActions"><button class="ghost" onclick="renderSceneMatchShellV9()">返回</button><button class="primary" onclick="confirmMergeSceneV9('${id}')">${target.enabled?'确认合并':'保存并开启'}</button></div></section></main></div>`,'sceneVoiceModal')}
function confirmMergeSceneV9(id){if(sceneEditCtx.resolutionCommitted)return;let target=S.services.find(x=>x.id===id),plan=sceneEditCtx.mergeTarget===id?sceneEditCtx.mergePlan:null;if(!target||!plan)return;sceneEditCtx.resolutionCommitted=true;target.actions=[...plan.actions];target.requires=sceneRequires(target.actions);target.enabled=true;target.record='刚刚 · 已合并语音创建草稿';localStorage.setItem('icarClawV3',JSON.stringify(S));renderAll();renderSceneResolutionV9(`已合并到“${target.name}”`,'没有创建重复场景；已有触发条件保持不变，新增与替换动作已生效。');toast(`${target.name}已合并并开启`)}

/* V9：以当前实车语音页为准，并把播报音色归入角色引擎 */
function ensureVoiceConfigV9(){let dirty=false;if(typeof S.voiceAssistantOn!=='boolean'){S.voiceAssistantOn=S.wake!==false;dirty=true}if(typeof S.customWakeWord!=='string'){S.customWakeWord='';dirty=true}if(typeof S.customReplyWord!=='string'){S.customReplyWord='';dirty=true}if(!['关闭','10s','30s','60s'].includes(S.conversationDuration)){S.conversationDuration='30s';dirty=true}if(typeof S.dialectMode!=='boolean'){S.dialectMode=false;dirty=true}if(typeof S.fullWake!=='boolean'){S.fullWake=true;dirty=true}if(typeof S.smartWake!=='boolean'){S.smartWake=true;dirty=true}S.wake=S.voiceAssistantOn;if(dirty)localStorage.setItem('icarClawV3',JSON.stringify(S))}
function voiceSwitchV9(key,label,desc){let off=!S.voiceAssistantOn;return `<div class="row ${off?'voiceSettingDisabled':''}"><div><h3>${label}</h3><p>${desc}</p></div><button class="switch ${S[key]?'on':''}" role="switch" aria-label="${escapeHtml(label)}" aria-checked="${!!S[key]}" ${off?'disabled':''} onclick="toggleVoiceSettingV9('${key}')"><i></i></button></div>`}
function renderVoiceV9(){ensureVoiceConfigV9();let assistant=document.getElementById('voiceAssistantRows'),wake=document.getElementById('wakeFreeRows'),conversation=document.getElementById('conversationRows');if(!assistant||!wake||!conversation)return;assistant.innerHTML=`<div class="row"><div><h3>语音助手</h3><p>说“你好 iCAR”或“你好咔宝”即可唤醒</p></div><button class="switch ${S.voiceAssistantOn?'on':''}" role="switch" aria-label="语音助手" aria-checked="${!!S.voiceAssistantOn}" onclick="setVoiceAssistantV9()"><i></i></button></div><div class="voicePhraseGrid"><button class="voicePhraseCard" ${S.voiceAssistantOn?'':'disabled'} onclick="editVoicePhraseV9('wake')"><b>自定义唤醒词</b><span>${escapeHtml(S.customWakeWord||'未设置')}</span>${uiIcon('edit')}</button><button class="voicePhraseCard" ${S.voiceAssistantOn?'':'disabled'} onclick="editVoicePhraseV9('reply')"><b>自定义应答词</b><span>${escapeHtml(S.customReplyWord||'未设置')}</span>${uiIcon('edit')}</button></div>`;wake.innerHTML=voiceSwitchV9('fullWake','主驾全时免唤醒','主驾无需唤醒词即可直接说出指令')+voiceSwitchV9('smartWake','智能免唤醒','根据上下文判断你是否正在与语音助手说话');conversation.innerHTML=`<div class="row ${S.voiceAssistantOn?'':'voiceSettingDisabled'}"><div><h3>连续对话时长</h3><p>一次唤醒后可持续语音对话</p></div><div class="voiceDuration">${['关闭','10s','30s','60s'].map(x=>`<button ${S.voiceAssistantOn?'':'disabled'} class="${S.conversationDuration===x?'active':''}" onclick="setConversationDurationV9('${x}')">${x}</button>`).join('')}</div></div>${voiceSwitchV9('dialectMode','方言模式','联网时支持四川话、粤语与普通话混合识别；可能影响唤醒率与识别率')}`}
function setVoiceAssistantV9(){ensureVoiceConfigV9();S.voiceAssistantOn=!S.voiceAssistantOn;S.wake=S.voiceAssistantOn;localStorage.setItem('icarClawV3',JSON.stringify(S));renderVoiceV9();toast(S.voiceAssistantOn?'语音助手已开启，原有子项配置已恢复':'语音助手已关闭，子项配置将保留')}
function toggleVoiceSettingV9(key){ensureVoiceConfigV9();if(!S.voiceAssistantOn||!['fullWake','smartWake','dialectMode'].includes(key))return;S[key]=!S[key];localStorage.setItem('icarClawV3',JSON.stringify(S));renderVoiceV9();toast('语音设置已更新')}
function setConversationDurationV9(value){ensureVoiceConfigV9();if(!S.voiceAssistantOn||!['关闭','10s','30s','60s'].includes(value))return;S.conversationDuration=value;localStorage.setItem('icarClawV3',JSON.stringify(S));renderVoiceV9();toast(`连续对话时长已设为${value}`)}
function editVoicePhraseV9(kind){ensureVoiceConfigV9();if(!S.voiceAssistantOn){toast('请先开启语音助手');return}let wake=kind==='wake',value=wake?S.customWakeWord:S.customReplyWord;modal(`${modalCloseButton()}<div class="eyebrow">我的语音助手</div><h2>${wake?'自定义唤醒词':'自定义应答词'}</h2><p class="sub">${wake?'新增一个你习惯的唤醒方式；“你好 iCAR”和“你好咔宝”仍然可用。':'设置唤醒后语音助手回应你的简短话语。'}</p><div class="form"><label>${wake?'唤醒词':'应答词'}</label><input id="voicePhraseInput" maxlength="8" value="${escapeHtml(value)}" placeholder="${wake?'例如：你好小爪':'例如：我在，请说'}" autocomplete="off"><div class="voicePhraseHint">支持 2–8 个中文、字母或数字，不能与另一项完全相同。</div><div class="voicePhraseError" id="voicePhraseError"></div></div><div class="actions"><button class="ghost" onclick="clearVoicePhraseV9('${kind}')">恢复未设置</button><button class="secondary" onclick="closeModal()">取消</button><button class="primary" onclick="saveVoicePhraseV9('${kind}')">保存</button></div>`,'voicePhraseModal')}
function saveVoicePhraseV9(kind){let input=document.getElementById('voicePhraseInput'),error=document.getElementById('voicePhraseError');if(!input)return;let value=input.value.trim(),other=kind==='wake'?S.customReplyWord:S.customWakeWord;if(!/^[\u4e00-\u9fa5A-Za-z0-9]{2,8}$/.test(value)){if(error)error.textContent='请输入 2–8 个中文、字母或数字';return}if(value===other){if(error)error.textContent='唤醒词与应答词不能完全相同';return}if(kind==='wake')S.customWakeWord=value;else S.customReplyWord=value;localStorage.setItem('icarClawV3',JSON.stringify(S));closeModal();renderVoiceV9();toast(`${kind==='wake'?'唤醒词':'应答词'}已保存`)}
function clearVoicePhraseV9(kind){if(kind==='wake')S.customWakeWord='';else S.customReplyWord='';localStorage.setItem('icarClawV3',JSON.stringify(S));closeModal();renderVoiceV9();toast('已恢复为未设置')}
function openPrivacyPolicyV12(){
  modal('<div class="privacyPolicyHead"><div><div class="eyebrow">账号、隐私与权限</div>'+
    '<h2>iCAR 智能语音助手隐私政策</h2></div>'+modalCloseButton()+'</div>'+
    '<p class="sub">以下为 Demo 的隐私功能说明，正式隐私政策以服务方发布文本为准。阅读说明不会开启、撤销或重置任何权限。</p>'+
    '<div class="block">'+
    '<div class="row"><div><h3>麦克风与语音识别</h3><p>仅在你点击语音体验、语音新建或编辑、继续说或重试时申请麦克风权限。打开页面、查看卡片或阅读本说明不会启动录音。</p><p>本 Demo 不保存原始音频。浏览器的语音识别服务可能通过网络处理音频；系统与浏览器的麦克风权限需分别在对应设置中管理。</p></div></div>'+
    '<div class="row"><div><h3>各项权限独立管理</h3><p>语音助手开关控制语音入口与当前语音会话，不会改变我的记忆、Face ID、声纹、座舱感知、车外感知或第三方服务的设置。这些能力仍由“账号、隐私与权限”中的对应入口分别管理。</p></div></div>'+
    '<div class="row"><div><h3>账号资产与数据保留</h3><p>退出账号后隐藏账号资产，重新登录原账号可恢复。关闭我的记忆会停止使用并隐藏内容，但不会删除已有数据；删除或清空记忆需要单独确认。</p></div></div>'+
    '<div class="row"><div><h3>第三方服务授权</h3><p>第三方服务需逐项授权；撤销后，依赖该服务的任务会暂停或请求重新授权，其他权限保持原状。本 Demo 仅模拟授权状态，不连接真实第三方账号或提交真实订单。</p></div></div>'+
    '</div><div class="actions"><button class="primary" onclick="closeModal()">返回</button></div>','privacyPolicyModal');
}
ROLE_OPTIONS.音色=[['甜美女声','清甜明亮，适合轻松日常'],['温柔女声','柔和舒缓，适合陪伴与长途'],['阳光男声','清晰有活力，信息播报自然'],['成熟男声','稳重沉着，适合导航与安全提醒']];
function ensureRoleConfigV9(){let dirty=!S.personal;S.personal=S.personal||{};let defaults={音色:'甜美女声',性格:'温暖陪伴',表达方式:'自然适中',主动程度:'适度主动',称呼:'杨先生'};Object.keys(defaults).forEach(k=>{if(!ROLE_OPTIONS[k].some(x=>x[0]===S.personal[k])){S.personal[k]=defaults[k];dirty=true}});if(dirty)localStorage.setItem('icarClawV3',JSON.stringify(S))}
function renderPersonalV9(){ensureRoleConfigV9();let icons={音色:'mic',性格:'sparkles',表达方式:'book',主动程度:'shield',称呼:'user'},tips={音色:'采用当前实车播报音色，选择你愿意长期听到的声音',性格:'决定 Claw 如何理解和回应你的情绪',表达方式:'决定回答是更简洁还是更有解释',主动程度:'决定 Claw 什么时候主动开口',称呼:'Claw 日常怎么称呼你'};document.getElementById('personalOptions').innerHTML=Object.entries(ROLE_OPTIONS).map(([g,ops])=>`<section class="roleSection" data-group="${g}"><div class="roleSectionHead"><span class="icon">${uiIcon(icons[g])}</span><div><h2>${g==='音色'?'播报音色':g}</h2><p>${tips[g]}</p></div></div><div class="roleChoices">${ops.map(o=>`<button class="roleChoice ${S.personal[g]===o[0]?'active':''}" onclick="pickPersonal('${g}','${o[0]}')"><b>${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div></section>`).join('');document.getElementById('previewName').textContent=`${S.personal.性格} · ${S.personal.音色}`;document.getElementById('previewCall').textContent=`${S.personal.称呼} · ${S.personal.主动程度}`;let lines={温暖陪伴:'前方开始拥堵，要不要换一条更轻松的路线？',冷静专业:'前方拥堵约增加 18 分钟，建议切换备选路线。',活泼有趣:'前面有点堵，要不要跟我换条更顺的路？'},line=lines[S.personal.性格];if(S.personal.表达方式==='简洁直接')line=S.personal.性格==='活泼有趣'?'前面堵了，换条路吗？':'前方拥堵，建议换路线。';if(S.personal.表达方式==='解释充分')line+=' 备选路线预计节省 12 分钟，且当前路况更稳定。';document.getElementById('previewLine').textContent='“'+line+'”'}

/* V10：主动服务按类型管理；推荐场景与我的场景共用规则详情 */
const REMOVED_SERVICE_IDS_V10=new Set(['table_child_guard','table_snow_mode','air','sentinel']);
const REMOVED_SERVICE_NAMES_V10=['乘员不适主动关怀','儿童乘车关怀','最优模式推荐','雪地模式推荐','空气净化','空气质量守护','哨兵守护'];
const SERVICE_CATEGORIES_V10=[['全部','sliders'],['安全守护','shield'],['出行导航','route'],['上车陪伴','user'],['内容推荐','media'],['我的场景','edit']];
const SERVICE_CATEGORY_BY_ID_V10={table_leave_guard:'安全守护',table_driver_guard:'安全守护',table_weather_prep:'安全守护',table_media_supply:'内容推荐',parking:'出行导航',preset_visibility:'安全守护',preset_identity:'上车陪伴',preset_nav_check:'出行导航',preset_scenic:'出行导航',preset_parking:'出行导航',preset_vehicle_alert:'安全守护',preset_welcome:'上车陪伴',preset_memory_welcome:'上车陪伴',preset_minor_accident:'安全守护',preset_praise:'上车陪伴'};
let activeServiceCategoryV10='全部';
function isRemovedServiceV10(s){let name=(s&&s.name)||'';return !!s&&s.source!=='我的场景'&&(REMOVED_SERVICE_IDS_V10.has(s.id)||REMOVED_SERVICE_NAMES_V10.some(x=>name.includes(x)))}
function migrateServiceCatalogV10(){let kept=TABLE_HOME_SCENES.filter(s=>!isRemovedServiceV10(s));if(kept.length!==TABLE_HOME_SCENES.length)TABLE_HOME_SCENES.splice(0,TABLE_HOME_SCENES.length,...kept);let dirty=false;(S.services||[]).forEach(s=>{if(isRemovedServiceV10(s)&&(!s.legacyHidden||s.enabled||s.tableScene)){s.enabled=false;s.legacyHidden=true;s.tableScene=false;dirty=true}});if(!S.serviceCatalogV10){S.serviceCatalogV10=true;dirty=true}if(dirty)localStorage.setItem('icarClawV3',JSON.stringify(S))}
function serviceCategoryV10(s){if(!s||s.source==='我的场景')return'我的场景';if(SERVICE_CATEGORY_BY_ID_V10[s.id])return SERVICE_CATEGORY_BY_ID_V10[s.id];let text=[s.name,s.desc,s.trigger,...(s.actions||[])].join(' ');if(/身份|迎宾|夸一夸/.test(text))return'上车陪伴';if(/内容|新闻|音乐|播报/.test(text))return'内容推荐';if(/导航|停车|景点|找车/.test(text))return'出行导航';return'安全守护'}
function serviceCategoryIconV10(category){let found=SERVICE_CATEGORIES_V10.find(x=>x[0]===category);return found?found[1]:'sparkles'}
function visibleServicesV10(){return(S.services||[]).filter(s=>!s.legacyHidden&&!isRemovedServiceV10(s)&&(S.loggedIn||s.source!=='我的场景'))}
