function thirdAuthV11(key,name=THIRD_LABELS_V11[key]){if(!Object.hasOwn(THIRD_LABELS_V11,key))return;if(!S.loggedIn){pendingTask=()=>thirdAuthV11(key,name);loginFlow('第三方服务授权需要绑定车主账号。');return}if(S.third[key]){confirmBox(`撤销${name}授权？`,'相关主动服务保留开启选择，但会暂停依赖部分；下次使用时需重新授权。已完成的任务不会回退。',()=>{S.third[key]=false;save();toast(name+'授权已撤销')},'撤销授权');return}modal(`${modalCloseButton()}<div class="eyebrow">账号授权</div><h2>连接${escapeHtml(name)}</h2><p class="sub">仅在你请求相关任务时使用此服务。你可随时在本页撤销授权。</p><p class="closureNote">本 Demo 模拟授权状态，不会登录外部账号或传输凭据。</p><div class="actions"><button class="ghost" onclick="closeModal()">暂不授权</button><button class="primary" onclick="finishThird('${key}')">同意并授权</button></div>`)}
function finishThirdV11(key){if(!S.loggedIn||!Object.hasOwn(THIRD_LABELS_V11,key))return;S.third[key]=true;save();hideModalV11();toast(THIRD_LABELS_V11[key]+'已授权');if(pendingSceneEnableV11)continueSceneEnableV11();else if(experienceCtx.phase==='awaitingAuthorization'&&!experienceCtx.cancelled)resumeVoiceTaskV11();else if(pendingTask){let next=pendingTask;pendingTask=null;next()}}
function toggleServiceV11(id){let scene=S.services.find(s=>s.id===id);if(!scene||scene.template||isRemovedServiceV10(scene))return;if(scene.source==='我的场景'&&!S.loggedIn){pendingTask=()=>toggleServiceV11(id);loginFlow();return}if(scene.enabled){scene.enabled=false;if(scene.source==='我的场景')addSceneHistoryV11(scene,'disable','手动关闭场景');save();toast(scene.name+'已关闭，已从首页移除');return}requestSceneEnableV11(id)}
function requestSceneEnableV11(id){let scene=S.services.find(s=>s.id===id);if(!scene||scene.template||isRemovedServiceV10(scene))return;pendingSceneEnableV11={id};continueSceneEnableV11()}
function continueSceneEnableV11(){let op=pendingSceneEnableV11,scene=op&&S.services.find(s=>s.id===op.id);if(!scene){pendingSceneEnableV11=null;return}let missing=missingRequirementsV11(sceneRequirementsV11(scene));if(!scene.trigger||!scene.actions.length){toast('请先补全触发条件与执行内容');pendingSceneEnableV11=null;openScene(scene.id);return}if(!missing.length){pendingSceneEnableV11=null;scene.enabled=true;if(scene.source==='我的场景')addSceneHistoryV11(scene,'enable','开启场景');save();openScene(scene.id);toast(scene.name+'已开启');return}let key=missing[0];if(key==='account'){pendingTask=()=>continueSceneEnableV11();loginFlow('登录后继续开启“'+scene.name+'”。');return}let action=key==='memoryData'?'<button class="primary" onclick="cancelSceneEnableV11();openSettings(\'memory\')">查看我的记忆</button>':key==='identity'?'<button class="secondary" onclick="identityFlow(\'face\')">录入 Face ID</button><button class="primary" onclick="identityFlow(\'voiceprint\')">录入声纹</button>':`<button class="primary" onclick="resolveScenePermissionV11('${key}')">${Object.hasOwn(THIRD_LABELS_V11,key)?'同意并授权':'同意并开启'}</button>`;modal(`${modalCloseButton()}<div class="eyebrow">恢复场景能力</div><h2>${escapeHtml(scene.name)}</h2><p class="sub">${key==='memoryData'?'当前没有可用的长期记忆。请先用语音明确偏好，或调整场景为固定参数。':'需要 '+escapeHtml(CAPABILITY_LABELS_V11[key])+' 才能继续。'}</p><div class="reviewStepsV11">${missing.map(k=>`<span>${escapeHtml(CAPABILITY_LABELS_V11[k])}</span>`).join('')}</div><p class="closureNote">只在你同意后开启权限；完成后自动返回该场景。取消不会删除已保存规则。</p><div class="actions"><button class="ghost" onclick="cancelSceneEnableV11()">暂不开启</button>${action}</div>`)}
function resolveScenePermissionV11(key){if(!pendingSceneEnableV11)return;if(Object.hasOwn(THIRD_LABELS_V11,key)){S.third[key]=true}else if(key==='memory')S.memoryOn=true;else if(['cabinEnv','cabinPeople','outside'].includes(key))S[key]=true;else return;save();continueSceneEnableV11()}
function cancelSceneEnableV11(){let id=pendingSceneEnableV11&&pendingSceneEnableV11.id;pendingSceneEnableV11=null;pendingTask=null;hideModalV11();if(id)openScene(id)}
function toggleSceneFromDetailV11(id){let s=S.services.find(x=>x.id===id);if(!s)return;if(s.enabled){toggleService(id);openScene(id)}else requestSceneEnableV11(id)}

