function voiceRequirementsV11(tab,skill,text){let req=[];if(tab==='出行助手'||/导航|路线|目的地|停车场|回家|去公司/.test(text))req.push('map');if(tab==='媒资娱乐'||/播放|音乐|听歌|放.*歌|新闻播报/.test(text)||skill==='氛围制造机器')req.push('media');if(tab==='生活服务'||/下单|订座|订餐|买.*票|订.*票|订.*酒店|停车费|帮.*订/.test(text))req.push('life');if(/补能|充电|快充/.test(text))req.push('charge');if(/预约.*(?:维修|保养|到店)|售后|救援|报修/.test(text))req.push('service');if(skill==='沿途识物')req.push('outside');return [...new Set(req)]}
function buildAgentTasksV11(tab,skill,text){let tasks=buildTasksBeforeV11(tab,skill,text),requirements=voiceRequirementsV11(tab,skill,text);experienceCtx.requirements=requirements;experienceCtx.degraded=[];if(!memoryUsableV11())experienceCtx.degraded.push('未读取长期记忆，仅使用本次明确表达');if(!S.cabinEnv&&['感受类控车','描述类控车','其他模糊类车控'].includes(skill))experienceCtx.degraded.push('未读取座舱环境，只按你的描述给出并执行明确设置');tasks=tasks.map(t=>({...t,status:'pending',detail:!memoryUsableV11()&&/Memory|记忆|历史偏好|内容偏好|驾驶人/.test(t.detail)?'使用本次明确表达，不读取个人记忆或身份资产':t.detail}));return [tasks[0],...requirements.map(key=>({name:'连接'+CAPABILITY_LABELS_V11[key],detail:'核对完成本次任务所需的授权',requires:[key],status:'pending'})),...tasks.slice(1)]}
function startSkillExperienceV11(tab,skill){if(tab!=='全局语音'&&!isAvailableSkillV12(tab,skill)){toast('该技能已更新，请返回首页重新选择');return}pendingTask=null;pendingSceneEnableV11=null;if(!S.voiceAssistantOn){modal(`${modalCloseButton()}<h2>语音助手已关闭</h2><p class="sub">开启后才会申请麦克风并进行语音体验。</p><div class="actions"><button class="ghost" onclick="closeModal()">返回</button><button class="primary" onclick="closeModal();openSettings('voice')">前往开启</button></div>`);return}startSkillBeforeV11(tab,skill);experienceCtx.turns=[];experienceCtx.funRound=0;experienceCtx.taskIndex=0;experienceCtx.businessResolved=false;experienceCtx.continuationDeadline=0}
function setTaskStateV11(index,state){let task=experienceCtx.tasks[index];if(task)task.status=state;let el=document.getElementById('agentTask'+index);if(!el)return;el.className='agentTask '+state;el.querySelector('.taskDot').innerHTML=state==='done'?uiIcon('check','sm'):state==='blocked'?uiIcon('lock','sm'):'';el.querySelector('em').textContent={done:'完成',running:'执行中',pending:'等待',blocked:'待授权',cancelled:'未执行'}[state]||state}
function voiceSceneProfileV13(tab,skill){let profiles={车辆控制:{className:'scene-car',label:'座舱控制编排',icon:'car',copy:'结合当前座舱状态，按安全顺序协同车辆能力'},出行助手:{className:'scene-route',label:'出行任务编排',icon:'route',copy:'持续规划目的地、路线与沿途服务'},车辆知识问答:{className:'scene-knowledge',label:'车辆知识与诊断',icon:'book',copy:'结合车辆知识和状态信息给出清晰判断'},生活服务:{className:'scene-life',label:'生活服务协同',icon:'service',copy:'整理需求、核对方案，并在确认后完成服务'},媒资娱乐:{className:'scene-media',label:'内容理解与播放',icon:'media',copy:'理解内容线索，定位资源并衔接播放'},iCAR趣玩:{className:'scene-fun',label:'iCAR 趣玩互动',icon:'sparkles',copy:'用专属玩法回应，让旅途多一点灵感'}},special={感受类控车:{icon:'wind',copy:'理解冷、热、闷、直吹等感受，组合座舱舒适设置'},描述类控车:{icon:'sliders',copy:'把对环境的自然描述转成一组明确车控动作'},多任务控车:{icon:'car',copy:'拆分多个车控目标，并按依赖与安全顺序完成'},常用地直达:{icon:'route',copy:'识别常用目的地，一句话完成路线准备'},生活搜索:{icon:'search',copy:'围绕地点、时间和偏好筛选可选目的地'},车辆知识问答:{icon:'book',copy:'结合车书知识，用容易理解的方式回答用车问题'},用车问题助手:{icon:'diagnostic',copy:'定位用户感知问题，给出处理建议和后续服务'},氛围制造机器:{icon:'celebration',copy:'生成灯光、音乐和角色表达协同的座舱氛围'},测测:{icon:'zodiac',copy:'根据本轮主题生成轻量测试和专属趣味结果'},塔罗牌:{icon:'fortune',copy:'用三张牌提供一个轻松、有边界的新视角'},沿途识物:{icon:'camera',copy:'识别视野中的建筑、动物或地标并随行讲解'},惬意午休:{icon:'leaf',copy:'联动休憩所需的座椅、空调与声音环境'},情景互动与品牌彩蛋:{icon:'celebration',copy:'识别人物与时机，触发专属车内互动'},海龟汤:{icon:'search',copy:'围绕谜面持续追问线索，直到推理出答案'}},base={...(profiles[tab]||{className:'scene-general',label:'Master Agent 编排',icon:'sparkles',copy:'理解完整需求，协调能力并依次完成任务'})};if(tab==='全局语音'){if(/导航|路线|回家|目的地/.test(experienceCtx.transcript||''))base={...profiles.出行助手};else if(/播放|音乐|歌曲|新闻|播客/.test(experienceCtx.transcript||''))base={...profiles.媒资娱乐};else if(/订|下单|餐厅|酒店|票/.test(experienceCtx.transcript||''))base={...profiles.生活服务};else if(/空调|座椅|车窗|灯|除雾|雨刷/.test(experienceCtx.transcript||''))base={...profiles.车辆控制}}return {...base,...(special[skill]||{})}}
