function renderAgentBoardV11(){let profile=voiceSceneProfileV13(experienceCtx.tab,experienceCtx.skill),count=experienceCtx.tasks.length,columns=Math.min(Math.max(count,3),5),degraded=experienceCtx.degraded&&experienceCtx.degraded.length?`<p class="closureNote">${experienceCtx.degraded.map(escapeHtml).join('<br>')}</p>`:'';modal(`<div class="idealVoiceShell voiceJourneyV13 ${profile.className}">${idealVoiceHeader(experienceCtx.skill,'正在执行')}<main class="idealVoiceCanvas voiceJourneyCanvas"><section class="voiceTypewriterV13 agentSummary"><span class="speakerV13">${uiIcon('mic')}本轮你说</span><p class="utteranceV13">${typewriterUtteranceV13(experienceCtx.transcript)}<span class="cursorV13"></span></p>${degraded}</section><section class="sceneExecutionV13"><header class="sceneHeroV13"><div class="sceneHeroCopyV13"><div class="eyebrow">${escapeHtml(profile.label)}</div><h3>${escapeHtml(experienceCtx.skill)}</h3><p>${escapeHtml(profile.copy)}</p></div>${sceneGlyphV13(profile)}</header><div class="planBodyV13"><div class="planLabelV13"><b>现有规划路径与执行顺序</b><span>${count} 项任务 · 自动执行</span></div><div class="taskFlow voicePlanFlowV13" id="agentTaskFlow" style="--plan-columns:${columns}">${experienceCtx.tasks.map((t,i)=>`<div class="agentTask ${escapeHtml(t.status||'pending')}" id="agentTask${i}"><span class="taskDot"></span><span><b>${escapeHtml(t.name)}</b><span>${escapeHtml(t.detail)}</span></span><em>等待</em></div>`).join('')}</div><div id="agentFinal" class="assistantReplySlotV13"><section class="assistantReplyV13 waiting"><span class="iCanV13">i</span><div><small>i · 智能副驾</small><p>正在跟随任务执行，完成后会在这里回复你。</p></div></section></div></div></section></main></div>`,`experienceModal voiceJourneyModal ${profile.className}`);experienceCtx.tasks.forEach((t,i)=>setTaskStateV11(i,t.status||'pending'))}
function runAgentTasksV11(sessionId){if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId||experienceCtx.phase!=='executing')return;let index=experienceCtx.taskIndex||0,task=experienceCtx.tasks[index];if(!task){showAgentResultV11(sessionId);return}let requirements=index>0?(experienceCtx.requirements||[]):[],missing=missingRequirementsV11(requirements);if(missing.length){experienceCtx.phase='awaitingAuthorization';experienceCtx.missing=missing;setTaskStateV11(index,'blocked');renderVoiceAuthorizationV11();return}setTaskStateV11(index,'running');let timer=setTimeout(()=>{if(experienceCtx.cancelled||experienceCtx.sessionId!==sessionId||experienceCtx.phase!=='executing')return;setTaskStateV11(index,'done');experienceCtx.taskIndex=index+1;runAgentTasksV11(sessionId)},580);experienceCtx.timers.push(timer)}
function renderVoiceAuthorizationV11(){let missing=experienceCtx.missing||[],key=missing[0],el=document.getElementById('agentFinal');if(!el||!key)return;let chip=document.getElementById('voiceStateChip');if(chip)chip.innerHTML=uiIcon('lock')+'等待授权';let button=key==='account'?'<button class="primary" onclick="loginForVoiceV11()">登录并继续原任务</button>':`<button class="primary" onclick="authorizeVoiceTaskV11('${key}')">${Object.hasOwn(THIRD_LABELS_V11,key)?'同意授权':'同意开启'}并继续</button>`;el.innerHTML=`<section class="closurePanel" id="voiceAuthorizationPanel"><h3>需要${escapeHtml(CAPABILITY_LABELS_V11[key])}</h3><p>“${escapeHtml(experienceCtx.transcript)}”已保留。当前任务暂停在这里，授权后自动接着执行，不会重复已完成步骤。</p><p class="closureNote">${Object.hasOwn(THIRD_LABELS_V11,key)?'本次仅演示服务授权，不连接真实第三方账户。':'不会替你开启其他权限。'}</p><div class="actions"><button class="ghost" onclick="cancelVoiceTaskV11()">取消本次任务</button>${button}</div></section>`;el.scrollIntoView({block:'nearest'})}
function loginForVoiceV11(){let sessionId=experienceCtx.sessionId;pendingTask=()=>{if(experienceCtx.cancelled||sessionId!==experienceCtx.sessionId)return;resumeVoiceTaskV11()};loginFlow('登录后恢复已保留的语音任务，未完成部分会自动继续。')}
function authorizeVoiceTaskV11(key){if(experienceCtx.cancelled||experienceCtx.phase!=='awaitingAuthorization')return;if(Object.hasOwn(THIRD_LABELS_V11,key)&&S.loggedIn)S.third[key]=true;else if(['cabinEnv','cabinPeople','outside'].includes(key))S[key]=true;else return;save();resumeVoiceTaskV11()}
