function businessFieldsMarkupV11(plan){return `<dl class="businessFieldsV11">${plan.fields.map(f=>`<div class="${f.required&&!f.value?'missing':''}" data-business-field="${escapeHtml(f.key)}"><dt>${escapeHtml(f.label)}</dt><dd>${f.key==='color'&&/^#[0-9A-F]{6}$/i.test(String(f.value))?`<span class="businessColorV11" style="background:${f.value}"></span>`:''}${escapeHtml(String(f.value===''?'请用语音补充':f.value))}<small>${escapeHtml(f.source)}</small></dd></div>`).join('')}</dl>`}
function businessSummaryV11(){let p=experienceCtx.businessPlan;return p?p.fields.filter(f=>f.value!==''&&f.key!=='provider').map(f=>f.label+'：'+f.value).join('；'):'请先补充本次服务要求。'}
function renderBusinessPlanV11(){let p=experienceCtx.businessPlan,el=document.getElementById('agentFinal'),chip=document.getElementById('voiceStateChip');if(!p||!el)return;let missing=p.missing.length,atmosphere=p.kind==='atmosphere';experienceCtx.phase=missing?'awaitingBusinessDetails':'awaitingBusiness';if(chip)chip.innerHTML=uiIcon(missing?'mic':'shield')+(missing?'等你补充':'待你确认');let prompt=missing?'请补充：'+p.missing.map(f=>f.label).join('、')+'。':'请核对方案；确认说完了不会代替本次业务确认。';el.innerHTML=`<section class="closurePanel" id="businessConfirmPanel"><div class="eyebrow">${atmosphere?'本次氛围':'服务方案'} · 第 ${p.revision} 版</div><h3>${missing?'还需要补充一点信息':atmosphere?'氛围方案已就绪':'请确认本次服务方案'}</h3><p>${escapeHtml(prompt)}</p>${businessFieldsMarkupV11(p)}<p class="closureNote">${escapeHtml(atmosphere?'配色和歌单为本机生成的演示方案，确认后仅更新本卡片，不控制真实灯光、媒体或已保存角色。':p.sourceNote)}</p><div class="actions"><button class="ghost" onclick="cancelBusinessV11()">取消本次方案</button><button class="secondary" onclick="continueExperienceV11('business')">${uiIcon('mic')}${missing?'用语音补充':'用语音修改'}</button>${missing?'':`<button class="primary" onclick="confirmBusinessV11()">${atmosphere?'确认应用演示方案':'确认方案并演示提交'}</button>`}</div></section>`;speakText(missing?prompt:'方案已经准备好，请检查具体内容后确认，也可以用语音修改。')}
