function confirmBusinessV11(){let p=experienceCtx.businessPlan;if(experienceCtx.phase!=='awaitingBusiness'||experienceCtx.businessResolved||!p||p.missing.length)return;let missing=missingRequirementsV11(experienceCtx.requirements||[]);if(missing.length){experienceCtx.phase='awaitingAuthorization';experienceCtx.missing=missing;renderVoiceAuthorizationV11();return}experienceCtx.businessResolved=true;experienceCtx.phase='businessSubmitting';let el=document.getElementById('agentFinal');if(el)el.innerHTML='<section class="closurePanel"><h3>正在确认并生成演示回执…</h3><p>不连接真实支付、订单或车辆服务。</p></section>';let sessionId=experienceCtx.sessionId,confirmed=JSON.parse(JSON.stringify(p));experienceCtx.timers.push(setTimeout(()=>{if(experienceCtx.cancelled||sessionId!==experienceCtx.sessionId||experienceCtx.phase!=='businessSubmitting')return;experienceCtx.phase='done';experienceCtx.businessReceipt={id:'DEMO-'+sessionId+'-'+confirmed.revision,plan:confirmed,submittedAt:new Date().toISOString(),simulated:true};if(confirmed.kind==='atmosphere')experienceCtx.appliedAtmosphere=confirmed;let outcome=confirmed.kind==='atmosphere'?'本次氛围演示已应用':'演示提交已完成',box=document.getElementById('agentFinal');if(box)box.innerHTML=`<section class="closurePanel"><h3>${outcome}</h3><div class="businessReceiptV11">演示回执：${escapeHtml(experienceCtx.businessReceipt.id)}<br>仅对第 ${confirmed.revision} 版方案确认一次</div>${businessFieldsMarkupV11(confirmed)}<p class="closureNote">${confirmed.kind==='atmosphere'?'本卡片已展示确认的配色、音乐与回应方式；不改变实车或长期角色设置。':'没有真实订单、扣款、出票或预约。商户资源和费用均为演示数据。'}</p>${continuationActionsV11()}</section>`;let chip=document.getElementById('voiceStateChip');if(chip)chip.innerHTML=uiIcon('check')+'已完成';setContinuationDeadlineV11();speakText(outcome)},750))}
function cancelBusinessV11(){if(!['awaitingBusiness','awaitingBusinessDetails'].includes(experienceCtx.phase))return;experienceCtx.businessResolved=true;experienceCtx.businessPlan=null;experienceCtx.businessReceipt=null;experienceCtx.phase='done';let el=document.getElementById('agentFinal');if(el)el.innerHTML='<section class="closurePanel"><h3>本次方案已取消</h3><p>没有提交订单、付款或应用氛围方案。</p>'+continuationActionsV11()+'</section>';setContinuationDeadlineV11()}
