function isVoiceEndIntentV11(text){let command=String(text||'').replace(/[\s。.!！?？,，、]/g,'');return /^(?:请|帮我)?(?:结束|退出|停止|结束(?:本次)?(?:对话|会话|语音|任务|体验|游戏)|退出(?:本次)?(?:语音|对话|会话|体验|游戏)|停止(?:本次)?(?:对话|会话|语音|任务|体验|游戏)|取消本次任务|不聊了|不玩了|不用了|先这样)(?:吧|了)?(?:谢谢)?$/.test(command)}
