    if((/加热/.test(l)&&/通风/.test(r))||(/通风/.test(l)&&/加热/.test(r)))return true;
    if((/内循环/.test(l)&&/外循环/.test(r))||(/外循环/.test(l)&&/内循环/.test(r)))return true;
