  let changes=[];
  for(let [field,label] of [['name','场景名称'],['trigger','触发条件'],['mode','执行方式']])if(Object.hasOwn(before,field)&&String(before[field]||'')!==String(after[field]||''))changes.push({field,label,kind:'update',before:String(before[field]||''),after:String(after[field]||'')});
