  for(let action of removed){let match=added.findIndex(a=>actionSlotV11(a)===actionSlotV11(action));if(match>=0)changes.push({field:'actions',label:'替换动作',kind:'replace',before:action,after:added.splice(match,1)[0]});else changes.push({field:'actions',label:'移除动作',kind:'remove',before:action,after:null})}
  for(let action of added)changes.push({field:'actions',label:'新增动作',kind:'add',before:null,after:action});
  if(!removed.length&&!added.length&&oldActions.join('\n')!==newActions.join('\n'))changes.push({field:'actions',label:'执行顺序',kind:'reorder',before:oldActions.join(' → '),after:newActions.join(' → ')});
