  if(matches.some(m=>m.level!=='similar')||(matches.length&&!sceneEditCtx.allowSimilar)){sceneEditCtx.matches=matches;sceneEditCtx.phase='decision';renderSceneMatchShellV9();return}
  if(!s){s={id:'custom'+Date.now()+'_'+Math.random().toString(36).slice(2,6),source:'我的场景',desc:'你用语音创建的专属主动场景',accent:'#718bff',history:[]};S.services.push(s)}
  Object.assign(s,{name:p.name,trigger:p.trigger,actions:[...p.actions],mode:p.mode||'提醒并执行',requires:sceneRequiresV11(p.actions,p.trigger)});
  let miss=depStatus(s);s.enabled=miss.length?false:editing?!!s.enabled:true;
  addSceneHistoryV11(s,editing?'edit':'create',editing?'通过语音修改并确认保存':'通过语音创建并确认',before);
  if(sceneEditCtx.origin==='habit')S.habitDismissedUntil=Date.now()+24*60*60*1000;
