function renderSavedSceneV11(s,title){let miss=depStatus(s);modal(`<div class="idealVoiceShell">${idealSceneHeader(title,'已完成')}<main class="idealVoiceCanvas">${sceneRuleSummaryV11(s,false)}<section class="closurePanel"><h3>${escapeHtml(title)}</h3><p>${miss.length?'规则已保存，当前保持关闭。补齐 '+miss.map(escapeHtml).join('、')+' 后可开启。':s.enabled?'已同步到首页，下次命中条件时运行。':'场景保留关闭状态，可按需开启。'}</p><div class="actions"><button class="ghost" onclick="closeModal()">完成</button><button class="secondary" onclick="openScene('${s.id}')">查看完整规则</button>${miss.length?`<button class="primary" onclick="requestSceneEnableV11('${s.id}')">恢复权限并开启</button>`:''}</div></section></main></div>`,'sceneVoiceModal')}
function resolveSceneMatchV11(action,id){let target=S.services.find(s=>s.id===id);if(!target)return;if(action==='view'){viewSceneMatchV9(id);return}if(action==='force'){keepDistinctSceneV11();return}if(action==='edit'){startSceneVoiceSession(id,'edit');return}if(action==='enable'){sceneEditCtx.applied=true;sceneEditCtx.phase='done';if(sceneEditCtx.origin==='habit'){S.habitDismissedUntil=Date.now()+24*60*60*1000;persistV11()}if(target.enabled&&!depStatus(target).length){openScene(id);toast('已使用现有场景，没有重复创建')}else requestSceneEnableV11(id)}}
function confirmMergeSceneV11(id){if(!S.loggedIn||sceneEditCtx.mode!=='create'||sceneEditCtx.applied||sceneEditCtx.resolutionCommitted)return;let target=S.services.find(s=>s.id===id),plan=sceneEditCtx.mergeTarget===id?sceneEditCtx.mergePlan:null;if(!target||target.source!=='我的场景'||!plan)return;let candidate={...target,actions:[...plan.actions]},error=validateSceneDraftV11(candidate),matches=findSceneMatchesV11(candidate,id).filter(m=>m.scene.id!==sceneEditCtx.id);if(error){toast(error);return}if(!sceneFieldChangesV11(target,candidate).length){renderSceneUnchangedV11(target);return}if(matches.some(m=>m.level==='conflict'||m.level==='exact')){sceneEditCtx.matches=matches;sceneEditCtx.phase='decision';renderSceneMatchShellV9();return}if(matches.length&&!sceneEditCtx.mergeSimilarConfirmed){sceneEditCtx.mergeSimilarConfirmed=true;modal(`${modalCloseButton()}<h2>合并后仍有相似场景</h2><p class="sub">与 ${matches.map(m=>escapeHtml(m.scene.name)).join('、')} 存在相似内容，没有互斥动作。确认保留这些差异后保存。</p><div class="actions"><button class="ghost" onclick="showMergePreviewV9('${id}')">返回合并预览</button><button class="primary" onclick="confirmMergeSceneV11('${id}')">保留差异并合并</button></div>`);return}let before=sceneRuleSnapshotV11(target);target.actions=[...plan.actions];target.requires=sceneRequiresV11(target.actions,target.trigger);if(depStatus(target).length)target.enabled=false;addSceneHistoryV11(target,'merge','确认合并执行内容，保留原触发条件',before);sceneEditCtx.resolutionCommitted=true;sceneEditCtx.applied=true;sceneEditCtx.phase='done';if(sceneEditCtx.origin==='habit')S.habitDismissedUntil=Date.now()+24*60*60*1000;save();renderSavedSceneV11(target,'已合并到已有场景')}
const sceneRuleBeforeV11=sceneRuleSummaryV10;
function sceneRuleSummaryV11(scene,history=false){let html=sceneRuleBeforeV11(scene,false);if(history&&!scene.template){let entries=Array.isArray(scene.history)&&scene.history.length?scene.history:[{at:'',summary:scene.record||'暂无变更记录'}];html+=`<div class="ruleSummaryItem"><small>${uiIcon('edit','sm')}变更记录 · 最近 ${Math.min(entries.length,20)} 条</small><div class="historyListV11">${entries.slice(0,20).map(item=>{let changes=Array.isArray(item.changes)?item.changes:item.before&&item.after?sceneFieldChangesV11(item.before,item.after):[];return `<article><small>${item.at?escapeHtml(new Date(item.at).toLocaleString('zh-CN',{hour12:false})):'历史记录'}</small><p>${escapeHtml(item.summary||'规则更新')}</p>${changes.length?`<ul class="historyFieldChangesV11">${changes.map(change=>`<li><b>${escapeHtml(change.label||'规则更新')}：</b>${change.kind==='add'?escapeHtml(change.after):change.kind==='remove'?escapeHtml(change.before)+' → 不再执行':escapeHtml(change.before)+' → '+escapeHtml(change.after)}</li>`).join('')}</ul>`:item.before&&!item.after?'<p class="historyLegacyNoteV11">此历史版本未保存字段明细。</p>':''}</article>`}).join('')}</div></div>`}return html}
function openSceneV11(id){let s=S.services.find(x=>x.id===id);if(!s||isRemovedServiceV10(s))return;if(s.source==='我的场景'&&!S.loggedIn){pendingTask=()=>openSceneV11(id);loginFlow();return}cleanupDemoPlayer();cleanupVoiceExperience();cleanupSceneVoice();let official=s.source==='iCAR 官方',miss=depStatus(s),type=official?'推荐场景':s.template?'我的场景模板':'我的场景',actions=s.template?`<button class="primary" onclick="startSceneVoiceSession('${id}','create')">${uiIcon('mic')}用语音创建</button>`:`${!official?`<button class="ghost sceneDangerV11" onclick="deleteSceneV11('${id}')">删除场景</button>`:''}<button class="secondary" onclick="toggleSceneFromDetailV11('${id}')">${s.enabled?'关闭场景':'开启场景'}</button>${!official?`<button class="primary" onclick="editMySceneV9('${id}')">${uiIcon('edit')}编辑场景</button>`:''}`;modal(`<section class="detailMediaShell">${sceneDetailHeaderV10(s,type)}<div class="detailMediaCinema">${sceneRuleSummaryV11(s,!official)}${miss.length?`<section class="closurePanel"><p>需要 ${miss.map(escapeHtml).join('、')}；依赖能力当前不会执行。</p><button class="secondary" onclick="requestSceneEnableV11('${id}')">恢复所需权限</button></section>`:''}</div><footer class="detailMediaFooter"><span>${uiIcon(official?'lock':'shield')}${official?'由 iCAR 维护，触发条件与执行内容不可编辑。':'先查看规则，点击编辑后才进入语音修改。'}</span><div class="actions"><button class="ghost" onclick="closeModal()">返回</button>${actions}</div></footer></section>`,'sceneDetailModal')}
function deleteSceneV11(id){let scene=S.services.find(s=>s.id===id);if(!S.loggedIn||!scene||scene.source!=='我的场景'||scene.template)return;confirmBox('删除“'+scene.name+'”？','删除后不再触发，也会从首页和管理页移除。删除后 10 秒内可撤销。',()=>{deletedSceneV11={scene:JSON.parse(JSON.stringify(scene)),index:S.services.indexOf(scene)};S.services=S.services.filter(s=>s.id!==id);save();let el=document.getElementById('toast');el.innerHTML=`<span>${escapeHtml(scene.name)}已删除</span><button onclick="undoDeleteSceneV11()">撤销</button>`;el.classList.add('show');clearTimeout(window._tt);clearTimeout(deleteUndoTimerV11);deleteUndoTimerV11=setTimeout(()=>{el.classList.remove('show');deletedSceneV11=null},10000)},'删除场景')}
