function speakWithRoleV11(text,config=S.personal,notice=null){try{if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)return;window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text),voices=window.speechSynthesis.getVoices().filter(v=>/^zh/i.test(v.lang)),index={'甜美女声':0,'温柔女声':1,'阳光男声':2,'成熟男声':3}[config.音色]||0;u.lang='zh-CN';if(voices.length)u.voice=voices[index%voices.length];u.pitch={'甜美女声':1.1,'温柔女声':1,'阳光男声':.95,'成熟男声':.85}[config.音色]||1;u.rate=1;u.onstart=()=>{if(notice)notice.textContent='正在使用浏览器系统声音试听；非实车专有音色。'};u.onend=()=>{if(notice)notice.textContent='试听结束。系统可用声音可能少于四种，正式音色需接入实车语音资源。'};u.onerror=()=>{if(notice)notice.textContent='当前声音不可播放，请检查浏览器声音权限后重试。'};window.speechSynthesis.speak(u)}catch(e){if(notice)notice.textContent='当前无法播放声音，可继续查看文字预览。'}}
