function saveVoicePhraseV11(kind){
  let input=document.getElementById('voicePhraseInput'),error=document.getElementById('voicePhraseError');
  if(!input||!S.voiceAssistantOn)return;
  let value=input.value.trim(),wake=kind==='wake';
  let valid=wake?/^[\u4e00-\u9fa5A-Za-z0-9]{2,8}$/.test(value):/^[\u4e00-\u9fa5A-Za-z0-9，。！？、,.!? ]{2,16}$/.test(value);
  if(!valid){error.textContent='请按上方规则输入';return}
  if(wake&&['你好icar','你好咔宝'].includes(value.replace(/\s/g,'').toLowerCase())){error.textContent='这是已保留的默认唤醒词，无需重复新增';return}
  let other=wake?S.customReplyWord:S.customWakeWord;
  if(value===other){error.textContent='唤醒词与应答词不能完全相同';return}
  if(wake)S.customWakeWord=value;else S.customReplyWord=value;
  persistV11();closeModal();renderVoiceV9();toast('已保存');
}
